export default function AdminSeedPage() {
    const [status, setStatus] = useState("");

    const handleCleanup = async () => {
        setStatus("Cleaning external hackathons...");
        try {
            const batch = writeBatch(db);
            const snapshot = await getDocs(collection(db, "hackathons"));
            let deletedCount = 0;

            snapshot.docs.forEach((doc) => {
                const data = doc.data();
                // Preserve DeVert events
                if (!data.title.toLowerCase().includes('devert')) {
                    batch.delete(doc.ref);
                    deletedCount++;
                }
            });

            if (deletedCount > 0) {
                await batch.commit();
                setStatus(`SUCCESS: Deleted ${deletedCount} external/duplicate hackathons. Now click SEED.`);
            } else {
                setStatus("No external hackathons found to delete.");
            }
        } catch (e) {
            console.error(e);
            setStatus("ERROR: " + e.message);
        }
    };

    const handleSeed = async () => {
        setStatus("Seeding...");
        try {
            const batch = writeBatch(db);

            // Helper to generate deterministic IDs from titles
            // e.g. "Global AI Hackathon 2025" -> "global-ai-hackathon-2025"
            // This prevents duplicates if you click seed multiple times.
            const createId = (str) => str.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/(^-|-$)+/g, '');

            // Hackathons
            HACKATHONS.forEach(hack => {
                const ref = doc(db, "hackathons", createId(hack.title));
                batch.set(ref, hack);
            });

            // Courses
            COURSES.forEach(course => {
                const ref = doc(db, "courses", createId(course.title));
                batch.set(ref, course);
            });

            // Postmortems (Use existing explicit ID)
            POSTMORTEMS.forEach(pm => {
                const ref = doc(db, "postmortems", pm.id);
                batch.set(ref, pm);
            });

            // Contests (Wargames)
            CONTESTS.forEach(contest => {
                const ref = doc(db, "contests", createId(contest.title));
                batch.set(ref, contest);
            });

            await batch.commit();
            setStatus("SUCCESS: Database populated! (Idempotent: No duplicates will be created)");
        } catch (e) {
            console.error(e);
            setStatus("ERROR: " + e.message);
        }
    };

    return (
        <div className="min-h-screen bg-black text-white p-20 pt-28 flex flex-col items-center">
            <h1 className="text-3xl font-bold mb-8">Admin Database Seeder</h1>
            <p className="mb-8 text-gray-400 max-w-md text-center">
                Clicking this will write dummy data (Hackathons & Courses) to your Firestore database.
                Ensure you are logged in if rules require it.
            </p>
            <div className="flex gap-4">
                <button
                    onClick={handleCleanup}
                    className="bg-red-500/10 border border-red-500 text-red-500 px-8 py-4 font-bold font-mono hover:bg-red-500 hover:text-black transition-colors"
                >
                    1. CLEAN OLD DATA
                </button>
                <button
                    onClick={handleSeed}
                    className="bg-neon-green text-black px-8 py-4 font-bold font-mono hover:opacity-90 transition-colors"
                >
                    2. SEED DATABASE
                </button>
            </div>
            {status && (
                <div className="mt-8 font-mono text-neon-cyan border border-neon-cyan p-4">
                    {status}
                </div>
            )}
        </div>
    );
}

"use client";

import { useState, useEffect } from "react";
import { db } from "@/lib/firebase";
import { collection, getDocs, query, orderBy, updateDoc, doc, where, writeBatch } from "firebase/firestore";
import { Loader2, CheckCircle, XCircle, Shield, User, Search, Edit, Save, X, StopCircle } from "lucide-react";
import { motion, AnimatePresence } from "framer-motion";

export default function ArchitectsAdminPage() {
    const [applications, setApplications] = useState([]);
    const [editedApplications, setEditedApplications] = useState([]);
    const [loading, setLoading] = useState(true);
    const [filter, setFilter] = useState("PENDING"); // PENDING, APPROVED, REJECTED

    // Edit Mode State
    const [isEditing, setIsEditing] = useState(false);
    const [saving, setSaving] = useState(false);

    const fetchApplications = async () => {
        setLoading(true);
        try {
            const q = query(collection(db, "executor_applications"), orderBy("createdAt", "desc"));
            const querySnapshot = await getDocs(q);
            const items = querySnapshot.docs.map(doc => ({ id: doc.id, ...doc.data() }));
            setApplications(items);
            setEditedApplications(JSON.parse(JSON.stringify(items)));
        } catch (error) {
            console.error("Error fetching applications:", error);
        } finally {
            setLoading(false);
        }
    };

    useEffect(() => {
        fetchApplications();
    }, []);

    const handleStatusUpdate = async (id, newStatus) => {
        try {
            await updateDoc(doc(db, "executor_applications", id), {
                status: newStatus
            });
            // If approving, we might also want to update the core User document to have 'role: executor'
            // For now, we just track the application status.
            fetchApplications();
        } catch (error) {
            console.error("Error updating status:", error);
            alert("Failed to update status");
        }
    };

    const handleEditChange = (id, field, value) => {
        setEditedApplications(prev => prev.map(app => {
            if (app.id === id) {
                return { ...app, [field]: value };
            }
            return app;
        }));
    };

    const saveChanges = async () => {
        setSaving(true);
        try {
            const batch = writeBatch(db);

            editedApplications.forEach(app => {
                // Only update if changed (optimization optional, but good practice)
                // For now, simpler to just update the ones in the current view or all
                // Since we have the whole list, let's just update all edited ones.
                // To be safe, we update only the fields we allow editing for.
                const docRef = doc(db, "executor_applications", app.id);
                const { id, createdAt, ...data } = app; // Exclude ID and createdAt from overwrite if needed, or just allow them
                batch.update(docRef, {
                    name: app.name,
                    email: app.email,
                    skills: app.skills,
                    availability: app.availability,
                    motivation: app.motivation,
                    portfolio: app.portfolio
                });
            });

            await batch.commit();
            setApplications(JSON.parse(JSON.stringify(editedApplications)));
            setIsEditing(false);
            alert("Changes saved successfully!");
        } catch (err) {
            console.error("Error saving changes:", err);
            alert("Failed to save changes: " + err.message);
        } finally {
            setSaving(false);
        }
    };

    const displayData = isEditing ? editedApplications : applications;
    const filteredApps = displayData.filter(app => app.status === filter);

    return (
        <div className="space-y-8 relative pb-20">
            <div className="flex justify-between items-end">
                <div>
                    <h1 className="text-3xl font-bold font-sans text-white mb-2">SQUAD OPS</h1>
                    <p className="text-gray-400 font-mono text-sm">Recruit, Vet, and Manage Architects.</p>
                </div>
                <div className="flex flex-col items-end gap-4">
                    <button
                        onClick={() => {
                            if (isEditing) {
                                setEditedApplications(JSON.parse(JSON.stringify(applications)));
                                setIsEditing(false);
                            } else {
                                setIsEditing(true);
                            }
                        }}
                        className={`border px-4 py-2 font-mono text-xs font-bold flex items-center gap-2 transition-colors ${isEditing
                            ? "bg-red-500/10 border-red-500 text-red-500 hover:bg-red-500 hover:text-white"
                            : "bg-white/5 border-white/10 text-white hover:bg-neon-cyan hover:text-black"
                            }`}
                    >
                        {isEditing ? <><X size={14} /> CANCEL_EDIT</> : <><Edit size={14} /> EDIT_DETAILS</>}
                    </button>

                    <div className="flex gap-2 bg-white/5 p-1 rounded border border-white/10">
                        {['PENDING', 'APPROVED', 'REJECTED'].map(status => (
                            <button
                                key={status}
                                onClick={() => setFilter(status)}
                                className={`px-4 py-2 text-xs font-mono rounded transition-colors ${filter === status
                                    ? 'bg-neon-cyan text-black font-bold'
                                    : 'text-gray-400 hover:text-white'
                                    }`}
                            >
                                {status}
                            </button>
                        ))}
                    </div>
                </div>
            </div>

            {loading ? (
                <div className="text-center py-20 text-neon-cyan animate-pulse font-mono">
                    ACCESSING_PERSONNEL_FILES...
                </div>
            ) : filteredApps.length === 0 ? (
                <div className="text-center py-20 border border-dashed border-white/10 rounded-lg text-gray-500 font-mono">
                    NO_RECORDS_FOUND_FOR_STATUS: {filter}
                </div>
            ) : (
                <div className="grid grid-cols-1 gap-4">
                    {filteredApps.map((app) => (
                        <motion.div
                            key={app.id}
                            initial={{ opacity: 0, y: 10 }}
                            animate={{ opacity: 1, y: 0 }}
                            className={`bg-[#050505] border p-6 rounded-lg flex flex-col md:flex-row justify-between gap-6 transition-colors ${isEditing ? 'border-neon-cyan/50 border-dashed' : 'border-white/10 hover:border-white/20'}`}
                        >
                            <div className="flex-1">
                                <div className="flex items-center gap-3 mb-3">
                                    {isEditing ? (
                                        <div className="flex flex-col gap-2 w-full">
                                            <input
                                                value={app.name}
                                                onChange={(e) => handleEditChange(app.id, 'name', e.target.value)}
                                                className="bg-white/5 border border-white/10 p-2 font-bold text-white text-lg w-full"
                                                placeholder="Name"
                                            />
                                            <input
                                                value={app.email}
                                                onChange={(e) => handleEditChange(app.id, 'email', e.target.value)}
                                                className="bg-white/5 border border-white/10 p-2 text-xs font-mono text-gray-400 w-full"
                                                placeholder="Email"
                                            />
                                        </div>
                                    ) : (
                                        <>
                                            <h3 className="text-xl font-bold text-white">{app.name}</h3>
                                            <span className="text-xs font-mono text-gray-500 bg-white/5 px-2 py-1 rounded border border-white/10">
                                                {app.email}
                                            </span>
                                        </>
                                    )}
                                </div>
                                <div className="grid md:grid-cols-2 gap-4 mb-4">
                                    <div>
                                        <div className="text-[10px] uppercase text-gray-500 font-mono mb-1">SKILLS</div>
                                        {isEditing ? (
                                            <input
                                                value={app.skills}
                                                onChange={(e) => handleEditChange(app.id, 'skills', e.target.value)}
                                                className="bg-white/5 border border-white/10 p-2 text-sm text-neon-cyan font-mono w-full"
                                            />
                                        ) : (
                                            <div className="text-sm text-neon-cyan font-mono">{app.skills}</div>
                                        )}
                                    </div>
                                    <div>
                                        <div className="text-[10px] uppercase text-gray-500 font-mono mb-1">AVAILABILITY</div>
                                        {isEditing ? (
                                            <input
                                                type="number"
                                                value={app.availability}
                                                onChange={(e) => handleEditChange(app.id, 'availability', e.target.value)}
                                                className="bg-white/5 border border-white/10 p-2 text-sm text-white font-mono w-full"
                                            />
                                        ) : (
                                            <div className="text-sm text-white font-mono">{app.availability || "N/A"} Hrs/Wk</div>
                                        )}
                                    </div>
                                </div>
                                <div>
                                    <div className="text-[10px] uppercase text-gray-500 font-mono mb-1">Motivation</div>
                                    {isEditing ? (
                                        <textarea
                                            value={app.motivation}
                                            onChange={(e) => handleEditChange(app.id, 'motivation', e.target.value)}
                                            className="bg-white/5 border border-white/10 p-2 text-sm text-gray-400 font-mono italic w-full h-20 resize-none"
                                        />
                                    ) : (
                                        <p className="text-sm text-gray-400 font-mono italic">"{app.motivation}"</p>
                                    )}
                                </div>
                                <div className="mt-4">
                                    {isEditing ? (
                                        <div>
                                            <label className="text-[10px] uppercase text-gray-500 font-mono">Portfolio Link</label>
                                            <input
                                                value={app.portfolio || ""}
                                                onChange={(e) => handleEditChange(app.id, 'portfolio', e.target.value)}
                                                className="bg-white/5 border border-white/10 p-2 text-xs text-blue-400 font-mono w-full"
                                                placeholder="https://..."
                                            />
                                        </div>
                                    ) : (
                                        app.portfolio && (
                                            <a href={app.portfolio} target="_blank" rel="noopener noreferrer" className="text-xs text-blue-400 hover:text-blue-300 underline font-mono">
                                                VIEW_PORTFOLIO_LINK
                                            </a>
                                        )
                                    )}
                                </div>
                            </div>

                            <div className="flex flex-row md:flex-col justify-center gap-3 border-t md:border-t-0 md:border-l border-white/10 pt-4 md:pt-0 md:pl-6 min-w-[150px]">
                                {app.status === 'PENDING' && !isEditing && (
                                    <>
                                        <button
                                            onClick={() => handleStatusUpdate(app.id, 'APPROVED')}
                                            className="flex-1 bg-neon-green/10 text-neon-green border border-neon-green/30 hover:bg-neon-green hover:text-black py-2 px-4 rounded font-mono text-xs font-bold transition-colors flex items-center justify-center gap-2"
                                        >
                                            <CheckCircle size={14} /> RECRUIT
                                        </button>
                                        <button
                                            onClick={() => handleStatusUpdate(app.id, 'REJECTED')}
                                            className="flex-1 bg-red-500/10 text-red-500 border border-red-500/30 hover:bg-red-500 hover:text-white py-2 px-4 rounded font-mono text-xs font-bold transition-colors flex items-center justify-center gap-2"
                                        >
                                            <XCircle size={14} /> REJECT
                                        </button>
                                    </>
                                )}
                                {app.status === 'APPROVED' && (
                                    <div className="text-neon-green font-mono text-sm font-bold flex items-center gap-2 justify-center h-full">
                                        <Shield size={16} /> OPERATIVE_ACTIVE
                                    </div>
                                )}
                                {app.status === 'REJECTED' && (
                                    <div className="text-red-500 font-mono text-sm font-bold flex items-center gap-2 justify-center h-full">
                                        <XCircle size={16} /> REJECTED
                                    </div>
                                )}
                                {isEditing && (
                                    <div className="text-gray-500 text-xs font-mono text-center">
                                        Status Editing Disabled <br />(Use Buttons)
                                    </div>
                                )}
                            </div>
                        </motion.div>
                    ))}
                </div>
            )}

            {/* Admin Save Bar */}
            <AnimatePresence>
                {isEditing && (
                    <motion.div
                        initial={{ y: 100 }}
                        animate={{ y: 0 }}
                        exit={{ y: 100 }}
                        className="fixed bottom-0 left-0 right-0 p-4 bg-black/90 backdrop-blur-md border-t border-neon-cyan z-50 flex items-center justify-between"
                    >
                        <div className="text-neon-cyan font-mono text-sm animate-pulse">
                            ADMIN_MODE_ACTIVE // UNSAVED_CHANGES
                        </div>
                        <div className="flex gap-4">
                            <button
                                onClick={() => {
                                    setIsEditing(false);
                                    setEditedApplications(JSON.parse(JSON.stringify(applications)));
                                }}
                                className="px-6 py-2 border border-red-500 text-red-500 font-mono text-sm hover:bg-red-500/10"
                            >
                                DISCARD
                            </button>
                            <button
                                onClick={saveChanges}
                                disabled={saving}
                                className="px-6 py-2 bg-neon-cyan text-black font-bold font-mono text-sm hover:opacity-80 disabled:opacity-50 flex items-center gap-2"
                            >
                                {saving ? <><StopCircle className="animate-spin" size={16} /> SAVING...</> : <><Save size={16} /> SAVE_CHANGES</>}
                            </button>
                        </div>
                    </motion.div>
                )}
            </AnimatePresence>
        </div>
    );
}

"use client";

import { useState, useEffect } from "react";
import { db } from "@/lib/firebase";
import {
    collection,
    getDocs,
    addDoc,
    updateDoc,
    deleteDoc,
    doc
} from "firebase/firestore";
import {
    Plus,
    Edit,
    Trash2,
    X,
    Save,
    Target,
    Zap,
    Briefcase,
    Shield,
    CheckCircle,
    Database
} from "lucide-react";
import { motion, AnimatePresence } from "framer-motion";

export default function BountiesManager() {
    const [bounties, setBounties] = useState([]);
    const [loading, setLoading] = useState(true);
    const [isModalOpen, setIsModalOpen] = useState(false);
    const [currentBounty, setCurrentBounty] = useState(null);
    const [dialog, setDialog] = useState({ show: false, message: "", type: "info" });

    // Initial Form State
    const initialFormState = {
        title: "",
        company: "",
        reward: "", // Stored as string e.g. "5000 XP"
        type: "Frontend", // Frontend, Backend, Design, Contract
        difficulty: "Easy", // Easy, Medium, Hard, Veteran
        status: "OPEN",
        description: "",
        requirements: "" // Newline separated
    };

    const [formData, setFormData] = useState(initialFormState);

    // Fetch Data
    const fetchBounties = async () => {
        setLoading(true);
        try {
            const querySnapshot = await getDocs(collection(db, "bounties"));
            const items = querySnapshot.docs.map(doc => ({
                id: doc.id,
                ...doc.data()
            }));
            setBounties(items);
        } catch (error) {
            console.error("Error fetching bounties:", error);
        } finally {
            setLoading(false);
        }
    };

    useEffect(() => {
        fetchBounties();
    }, []);

    // Handlers
    const openAddModal = () => {
        setCurrentBounty(null);
        setFormData(initialFormState);
        setIsModalOpen(true);
    };

    const openEditModal = (bounty) => {
        setCurrentBounty(bounty);
        setFormData({
            title: bounty.title,
            company: bounty.company,
            reward: bounty.reward,
            type: bounty.type,
            difficulty: bounty.difficulty,
            status: bounty.status,
            description: bounty.description,
            requirements: bounty.requirements ? bounty.requirements.join("\n") : ""
        });
        setIsModalOpen(true);
    };

    const handleDelete = async (docId) => {
        if (!confirm("Delete this bounty contract?")) return;
        try {
            await deleteDoc(doc(db, "bounties", docId));
            setBounties(prev => prev.filter(b => b.id !== docId));
        } catch (error) {
            setDialog({ show: true, message: "Failed to delete: " + error.message, type: "error" });
        }
    };

    const handleSave = async (e) => {
        e.preventDefault();

        const processArray = (str) => str.split('\n').map(s => s.trim()).filter(s => s);

        const dataToSave = {
            ...formData,
            requirements: processArray(formData.requirements),
            updatedAt: new Date().toISOString()
        };

        try {
            if (currentBounty) {
                const docRef = doc(db, "bounties", currentBounty.id);
                await updateDoc(docRef, dataToSave);
                setBounties(prev => prev.map(b => b.id === currentBounty.id ? { ...b, ...dataToSave } : b));
            } else {
                const docRef = await addDoc(collection(db, "bounties"), {
                    ...dataToSave,
                    createdAt: new Date().toISOString()
                });
                setBounties(prev => [...prev, { id: docRef.id, ...dataToSave }]);
            }
            setIsModalOpen(false);
        } catch (error) {
            setDialog({ show: true, message: "Failed to save: " + error.message, type: "error" });
        }
    };

    const handleSeed = async () => {
        if (!confirm("WARNING: This will DELETE ALL existing BOUNTIES and replace them with REAL XP TASKS. Proceed?")) return;

        const realBounties = [
            {
                title: "Optimise React Re-renders",
                company: "OpenSource",
                reward: "2500 XP",
                type: "Frontend",
                difficulty: "Medium",
                status: "OPEN",
                description: "Fix excessive re-renders in the ChatComponent. Performance is degrading on mobile.",
                requirements: ["Profile with React DevTools", "Implement React.memo / useMemo", "Verify <16ms render time"]
            },
            {
                title: "Dark Mode Contrast Fix",
                company: "DeVert Internal",
                reward: "1000 XP",
                type: "Design",
                difficulty: "Easy",
                status: "OPEN",
                description: "Audit the new dark mode palette. Some text inputs have low contrast ratios.",
                requirements: ["Check WCAG AA compliance", "Update Tailwind config", "Test on OLED screens"]
            },
            {
                title: "Secure API Endpoints",
                company: "DeFi Protocol",
                reward: "15000 XP",
                type: "Backend",
                difficulty: "Hard",
                status: "OPEN",
                description: "Implement Rate Limiting and JWT validation for the user_profile routes.",
                requirements: ["Redis based rate limiting", "Verify JWT signature", "Write integration tests"]
            },
            {
                title: "Smart Contract Audit",
                company: "Web3 Foundation",
                reward: "50000 XP",
                type: "Contract",
                difficulty: "Veteran",
                status: "OPEN",
                description: "Find re-entrancy vulnerabilities in the Vault contract before mainnet launch.",
                requirements: ["Analyze Solidity code", "Write PoC exploit", "Suggest fix"]
            },
            {
                title: "Migrate to Next.js 15",
                company: "Legacy App",
                reward: "8000 XP",
                type: "Frontend",
                difficulty: "Hard",
                status: "OPEN",
                description: "Upgrade the codebase from Pages router to App router.",
                requirements: ["Refactor routing logic", "Implement Server Components", "Ensure SEO parity"]
            },
            {
                title: "Write Documentation",
                company: "Community",
                reward: "500 XP",
                type: "Design",
                difficulty: "Easy",
                status: "OPEN",
                description: "Create a clear 'Getting Started' guide for new contributors.",
                requirements: ["Markdown format", "Include setup screenshots", "Explain directory structure"]
            }
        ];

        setLoading(true);
        try {
            // 1. Clear existing data
            const snapshot = await getDocs(collection(db, "bounties"));
            const deletePromises = snapshot.docs.map(d => deleteDoc(doc(db, "bounties", d.id)));
            await Promise.all(deletePromises);

            // 2. Add new data
            const addPromises = realBounties.map(b =>
                addDoc(collection(db, "bounties"), {
                    ...b,
                    createdAt: new Date().toISOString()
                })
            );
            await Promise.all(addPromises);
            setDialog({ show: true, message: "Mercenary Board Refreshed with XP Tasks.", type: "success" });
            fetchBounties();
        } catch (error) {
            console.error("Seeding failed:", error);
            setDialog({ show: true, message: "Seeding failed: " + error.message, type: "error" });
        } finally {
            setLoading(false);
        }
    };

    return (
        <div className="relative min-h-[80vh]">
            {/* Dialog Modal */}
            {dialog.show && (
                <div className="fixed inset-0 z-[60] flex items-center justify-center p-4 bg-black/80 backdrop-blur-sm animate-in fade-in duration-200">
                    <div className="bg-[#0a0a0a] border border-white/10 p-8 max-w-md w-full relative shadow-2xl flex flex-col items-center text-center">
                        <div className={`mb-4 p-4 rounded-full ${dialog.type === 'error' ? 'bg-red-500/10 text-red-500' : 'bg-neon-green/10 text-neon-green'}`}>
                            {dialog.type === 'error' ? <Shield size={32} /> : <CheckCircle size={32} />}
                        </div>
                        <h3 className="text-xl font-bold font-sans text-white mb-2">{dialog.type === 'error' ? 'SYSTEM_ERROR' : 'OPERATION_COMPLETE'}</h3>
                        <p className="font-mono text-sm text-gray-400 mb-6">{dialog.message}</p>
                        <button
                            onClick={() => setDialog({ ...dialog, show: false })}
                            className="w-full bg-white/10 hover:bg-white/20 text-white font-mono py-2 text-sm uppercase tracking-wider transition-colors"
                        >
                            CLOSE_DIALOG
                        </button>
                    </div>
                </div>
            )}

            <div className="flex justify-between items-center mb-8">
                <div>
                    <h1 className="text-3xl font-bold font-sans text-white">MERCENARY_BOARD</h1>
                    <p className="font-mono text-xs text-gray-500">Manage active contracts and rewards.</p>
                </div>
                <div className="flex gap-2">
                    <button
                        onClick={handleSeed}
                        className="bg-white/10 border border-white/20 text-white px-4 py-2 font-bold font-mono text-sm flex items-center hover:bg-white hover:text-black transition-all"
                    >
                        <Database size={16} className="mr-2" /> SEED_XP_TASKS
                    </button>
                    <button
                        onClick={openAddModal}
                        className="bg-yellow-500 text-black px-4 py-2 font-bold font-mono text-sm flex items-center hover:bg-white transition-colors"
                    >
                        <Plus size={16} className="mr-2" /> CREATE_CONTRACT
                    </button>
                </div>
            </div>

            {loading ? (
                <div className="text-yellow-500 font-mono animate-pulse">Scanning contracts...</div>
            ) : (
                <div className="grid grid-cols-1 gap-4">
                    {bounties.map((bounty) => (
                        <div
                            key={bounty.id}
                            className={`bg-black/40 border p-6 flex flex-col md:flex-row justify-between items-start md:items-center hover:border-yellow-500/50 transition-colors group ${bounty.status === 'OPEN' ? 'border-white/10' : 'border-red-900/30 opacity-50'}`}
                        >
                            <div className="flex-1">
                                <div className="flex items-center gap-3 mb-2">
                                    <span className={`px-2 py-0.5 text-[10px] font-mono border ${bounty.difficulty === 'Easy' ? 'border-neon-green text-neon-green' :
                                            bounty.difficulty === 'Medium' ? 'border-yellow-500 text-yellow-500' :
                                                'border-red-500 text-red-500'
                                        }`}>
                                        {bounty.difficulty}
                                    </span>
                                    <h3 className="text-xl font-bold font-sans text-white">{bounty.title}</h3>
                                </div>
                                <p className="text-gray-400 text-sm mb-3 max-w-2xl">{bounty.description}</p>
                                <div className="flex flex-wrap gap-4 text-xs font-mono text-gray-500">
                                    <span className="flex items-center text-neon-cyan"><Briefcase size={12} className="mr-1" /> {bounty.company}</span>
                                    <span className="flex items-center text-yellow-500 font-bold"><Zap size={12} className="mr-1" /> {bounty.reward}</span>
                                    <span className="flex items-center"><Target size={12} className="mr-1" /> {bounty.type}</span>
                                </div>
                            </div>

                            <div className="flex items-center gap-2 mt-4 md:mt-0 opacity-0 group-hover:opacity-100 transition-opacity">
                                <button onClick={() => openEditModal(bounty)} className="p-2 hover:bg-white/10 text-yellow-500 rounded transition-colors"><Edit size={18} /></button>
                                <button onClick={() => handleDelete(bounty.id)} className="p-2 hover:bg-red-500/10 text-red-500 rounded transition-colors"><Trash2 size={18} /></button>
                            </div>
                        </div>
                    ))}
                    {bounties.length === 0 && <div className="text-center py-20 text-gray-500 font-mono">NO CONTRACTS FOUND.</div>}
                </div>
            )}

            {/* Modal */}
            <AnimatePresence>
                {isModalOpen && (
                    <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
                        <motion.div
                            initial={{ opacity: 0 }} onClick={() => setIsModalOpen(false)} className="absolute inset-0 bg-black/80 backdrop-blur-sm"
                        />
                        <motion.div
                            initial={{ opacity: 0, scale: 0.95 }} animate={{ opacity: 1, scale: 1 }}
                            className="relative w-full max-w-2xl bg-[#0a0a0a] border border-white/20 p-8 shadow-2xl z-10"
                        >
                            <button onClick={() => setIsModalOpen(false)} className="absolute top-4 right-4 text-gray-500 hover:text-white"><X size={20} /></button>
                            <h2 className="text-xl font-bold font-sans text-white mb-6">CONTRACT_EDITOR</h2>

                            <form onSubmit={handleSave} className="space-y-4">
                                <div className="grid grid-cols-2 gap-4">
                                    <div>
                                        <label className="label">TITLE</label>
                                        <input className="input" required value={formData.title} onChange={e => setFormData({ ...formData, title: e.target.value })} />
                                    </div>
                                    <div>
                                        <label className="label">COMPANY / CLIENT</label>
                                        <input className="input" required value={formData.company} onChange={e => setFormData({ ...formData, company: e.target.value })} />
                                    </div>
                                </div>

                                <div className="grid grid-cols-3 gap-4">
                                    <div>
                                        <label className="label">REWARD (XP)</label>
                                        <input className="input" required value={formData.reward} onChange={e => setFormData({ ...formData, reward: e.target.value })} placeholder="5000 XP" />
                                    </div>
                                    <div>
                                        <label className="label">TYPE</label>
                                        <select className="input" value={formData.type} onChange={e => setFormData({ ...formData, type: e.target.value })}>
                                            <option>Frontend</option>
                                            <option>Backend</option>
                                            <option>Design</option>
                                            <option>Contract</option>
                                        </select>
                                    </div>
                                    <div>
                                        <label className="label">DIFFICULTY</label>
                                        <select className="input" value={formData.difficulty} onChange={e => setFormData({ ...formData, difficulty: e.target.value })}>
                                            <option>Easy</option>
                                            <option>Medium</option>
                                            <option>Hard</option>
                                            <option>Veteran</option>
                                        </select>
                                    </div>
                                </div>

                                <div>
                                    <label className="label">DESCRIPTION</label>
                                    <textarea className="input h-20 resize-none" required value={formData.description} onChange={e => setFormData({ ...formData, description: e.target.value })} />
                                </div>

                                <div>
                                    <label className="label">REQUIREMENTS (One per line)</label>
                                    <textarea className="input h-32 resize-none font-mono text-xs" required value={formData.requirements} onChange={e => setFormData({ ...formData, requirements: e.target.value })} placeholder="- Node.js v18+&#10;- Must include tests" />
                                </div>

                                <button type="submit" className="w-full bg-yellow-500 text-black font-bold font-mono py-3 mt-4 hover:bg-white transition-colors">PUBLISH CONTRACT</button>
                            </form>
                        </motion.div>
                    </div>
                )}
            </AnimatePresence>
            <style jsx>{`
                .label { display: block; font-size: 0.65rem; font-family: monospace; color: #9ca3af; margin-bottom: 0.25rem; }
                .input { width: 100%; background: rgba(255,255,255,0.05); border: 1px solid rgba(255,255,255,0.1); padding: 0.5rem; color: white; font-family: sans-serif; outline: none; transition: border-color 0.2s; }
                .input:focus { border-color: #EAB308; }
            `}</style>
        </div>
    );
}

"use client";

import { useState, useEffect } from "react";
import { db } from "@/lib/firebase";
import {
    collection,
    getDocs,
    addDoc,
    updateDoc,
    deleteDoc,
    doc
} from "firebase/firestore";
import {
    Plus,
    Edit,
    Trash2,
    X,
    Save,
    Activity,
    CheckCircle,
    Shield,
    Database,
    Trophy
} from "lucide-react";
import { motion, AnimatePresence } from "framer-motion";
import DatePicker from "react-datepicker";
import "react-datepicker/dist/react-datepicker.css";

export default function ContestsManager() {
    const [contests, setContests] = useState([]);
    const [loading, setLoading] = useState(true);
    const [isModalOpen, setIsModalOpen] = useState(false);
    const [currentContest, setCurrentContest] = useState(null);
    const [dialog, setDialog] = useState({ show: false, message: "", type: "info" });

    // Initial Form State
    const initialFormState = {
        title: "",
        contestCode: "",
        description: "",
        date: new Date().toISOString(),
        duration: "2 Hours",
        level: "MEDIUM", // EASY, MEDIUM, HARD, INSANE
        tags: "", // Comma separated
        status: "UPCOMING", // UPCOMING, LIVE, PAST
        host: "DeVert System"
    };

    const [formData, setFormData] = useState(initialFormState);

    // Fetch Data
    const fetchContests = async () => {
        setLoading(true);
        try {
            const querySnapshot = await getDocs(collection(db, "contests"));
            const items = querySnapshot.docs.map(doc => ({
                id: doc.id,
                ...doc.data()
            }));
            setContests(items);
        } catch (error) {
            console.error("Error fetching contests:", error);
        } finally {
            setLoading(false);
        }
    };

    useEffect(() => {
        fetchContests();
    }, []);

    // Handlers
    const openAddModal = () => {
        setCurrentContest(null);
        setFormData(initialFormState);
        setIsModalOpen(true);
    };

    const openEditModal = (contest) => {
        setCurrentContest(contest);
        setFormData({
            title: contest.title,
            contestCode: contest.contestCode || "",
            description: contest.description,
            date: contest.date,
            duration: contest.duration,
            level: contest.level,
            tags: Array.isArray(contest.tags) ? contest.tags.join(", ") : contest.tags,
            status: contest.status,
            host: contest.host || "DeVert System"
        });
        setIsModalOpen(true);
    };

    const handleDelete = async (docId) => {
        if (!confirm("Delete this contest?")) return;
        try {
            await deleteDoc(doc(db, "contests", docId));
            setContests(prev => prev.filter(c => c.id !== docId));
        } catch (error) {
            setDialog({ show: true, message: "Failed to delete: " + error.message, type: "error" });
        }
    };

    const handleSave = async (e) => {
        e.preventDefault();

        const processTags = (str) => str.split(',').map(s => s.trim()).filter(s => s);

        const dataToSave = {
            ...formData,
            tags: processTags(formData.tags),
            updatedAt: new Date().toISOString()
        };

        try {
            if (currentContest) {
                const docRef = doc(db, "contests", currentContest.id);
                await updateDoc(docRef, dataToSave);
                setContests(prev => prev.map(c => c.id === currentContest.id ? { ...c, ...dataToSave } : c));
            } else {
                const docRef = await addDoc(collection(db, "contests"), {
                    ...dataToSave,
                    createdAt: new Date().toISOString()
                });
                setContests(prev => [...prev, { id: docRef.id, ...dataToSave }]);
            }
            setIsModalOpen(false);
        } catch (error) {
            setDialog({ show: true, message: "Failed to save: " + error.message, type: "error" });
        }
    };

    const handleSeed = async () => {
        if (!confirm("WARNING: This will DELETE ALL existing CONTESTS and replace them with REAL AGENT CHALLENGES. Proceed?")) return;

        const realContests = [
            {
                title: "CodeForces Round #950 (Div. 2)",
                contestCode: "CF-950-D2",
                description: "Standard 2-hour round for Division 2 participants. Good for practice.",
                date: "2026-02-15T14:30:00.000Z",
                duration: "2 Hours",
                level: "MEDIUM",
                tags: ["Greedy", "Math", "Implementation"],
                status: "UPCOMING",
                host: "CodeForces"
            },
            {
                title: "LeetCode Weekly Contest 440",
                contestCode: "LC-WC-440",
                description: "Solve 4 algorithmic problems in 90 minutes. Global ranking.",
                date: "2026-02-18T08:00:00.000Z",
                duration: "1.5 Hours",
                level: "EASY",
                tags: ["Arrays", "DP", "Trees"],
                status: "UPCOMING",
                host: "LeetCode"
            },
            {
                title: "Google Code Jam 2026 - Qualification",
                contestCode: "GCJ-2026-Q",
                description: "The first round of GCJ. You need 30 points to advance.",
                date: "2026-04-05T00:00:00.000Z",
                duration: "27 Hours",
                level: "HARD",
                tags: ["Ad-hoc", "Interactive", "Performance"],
                status: "UPCOMING",
                host: "Google"
            },
            {
                title: "AtCoder Beginner Contest 392",
                contestCode: "ABC-392",
                description: "Perfect for beginners to start competitive programming.",
                date: "2026-02-10T20:00:00.000Z",
                duration: "100 Mins",
                level: "EASY",
                tags: ["Logic", "Basic Algo"],
                status: "UPCOMING",
                host: "AtCoder"
            },
            {
                title: "Meta Hacker Cup - Round 1",
                contestCode: "MHC-26-R1",
                description: "Advanced algorithmic challenges. Top 500 advance.",
                date: "2026-05-20T10:00:00.000Z",
                duration: "24 Hours",
                level: "INSANE",
                tags: ["Graph Theory", "Number Theory", "Flows"],
                status: "UPCOMING",
                host: "Meta"
            },
            {
                title: "DeVert Monthly Blitz",
                contestCode: "DV-BLITZ-01",
                description: "Internal squadron showdown. Winner takes all XP.",
                date: new Date().toISOString(), // TODAY/LIVE
                duration: "4 Hours",
                level: "MEDIUM",
                tags: ["Speed", "Optimization"],
                status: "LIVE",
                host: "DeVert System"
            }
        ];

        setLoading(true);
        try {
            // 1. Clear existing data
            const snapshot = await getDocs(collection(db, "contests"));
            const deletePromises = snapshot.docs.map(d => deleteDoc(doc(db, "contests", d.id)));
            await Promise.all(deletePromises);

            // 2. Add new data
            const addPromises = realContests.map(c =>
                addDoc(collection(db, "contests"), {
                    ...c,
                    createdAt: new Date().toISOString()
                })
            );
            await Promise.all(addPromises);
            setDialog({ show: true, message: "Agent War Games Refreshed.", type: "success" });
            fetchContests();
        } catch (error) {
            console.error("Seeding failed:", error);
            setDialog({ show: true, message: "Seeding failed: " + error.message, type: "error" });
        } finally {
            setLoading(false);
        }
    };

    return (
        <div className="relative min-h-[80vh]">
            {/* Dialog Modal */}
            {dialog.show && (
                <div className="fixed inset-0 z-[60] flex items-center justify-center p-4 bg-black/80 backdrop-blur-sm animate-in fade-in duration-200">
                    <div className="bg-[#0a0a0a] border border-white/10 p-8 max-w-md w-full relative shadow-2xl flex flex-col items-center text-center">
                        <div className={`mb-4 p-4 rounded-full ${dialog.type === 'error' ? 'bg-red-500/10 text-red-500' : 'bg-neon-green/10 text-neon-green'}`}>
                            {dialog.type === 'error' ? <Shield size={32} /> : <CheckCircle size={32} />}
                        </div>
                        <h3 className="text-xl font-bold font-sans text-white mb-2">{dialog.type === 'error' ? 'SYSTEM_ERROR' : 'OPERATION_COMPLETE'}</h3>
                        <p className="font-mono text-sm text-gray-400 mb-6">{dialog.message}</p>
                        <button
                            onClick={() => setDialog({ ...dialog, show: false })}
                            className="w-full bg-white/10 hover:bg-white/20 text-white font-mono py-2 text-sm uppercase tracking-wider transition-colors"
                        >
                            CLOSE_DIALOG
                        </button>
                    </div>
                </div>
            )}

            <div className="flex justify-between items-center mb-8">
                <div>
                    <h1 className="text-3xl font-bold font-sans text-white">AGENT_WAR_GAMES_ARENA</h1>
                    <p className="font-mono text-xs text-gray-500">Manage agent-based competitive events.</p>
                </div>
                <div className="flex gap-2">
                    <button
                        onClick={handleSeed}
                        className="bg-white/10 border border-white/20 text-white px-4 py-2 font-bold font-mono text-sm flex items-center hover:bg-white hover:text-black transition-all"
                    >
                        <Database size={16} className="mr-2" /> SEED_REAL_DATA
                    </button>
                    <button
                        onClick={openAddModal}
                        className="bg-neon-green text-black px-4 py-2 font-bold font-mono text-sm flex items-center hover:bg-white transition-colors"
                    >
                        <Plus size={16} className="mr-2" /> NEW_EVENT
                    </button>
                </div>
            </div>

            {loading ? (
                <div className="text-neon-green font-mono animate-pulse">Scanning frequencies...</div>
            ) : (
                <div className="grid grid-cols-1 gap-4">
                    {contests.map((contest) => (
                        <div
                            key={contest.id}
                            className={`bg-black/40 border p-6 flex flex-col md:flex-row justify-between items-start md:items-center hover:border-neon-green/50 transition-colors group ${contest.status === 'LIVE' ? 'border-neon-green/50' : 'border-white/10'}`}
                        >
                            <div className="flex-1">
                                <div className="flex items-center gap-3 mb-2">
                                    <span className={`px-2 py-0.5 text-[10px] font-mono border ${contest.status === 'LIVE' ? 'bg-neon-green text-black border-neon-green animate-pulse' :
                                        contest.status === 'UPCOMING' ? 'text-neon-cyan border-neon-cyan' :
                                            'text-gray-500 border-gray-500'
                                        }`}>
                                        {contest.status}
                                    </span>
                                    <h3 className="text-xl font-bold font-sans text-white">{contest.title}</h3>
                                    {contest.contestCode && <span className="px-2 py-0.5 text-[10px] font-mono border text-white/50 border-white/20">{contest.contestCode}</span>}
                                </div>
                                <p className="text-gray-400 text-sm mb-3 max-w-2xl">{contest.description}</p>
                                <div className="flex flex-wrap gap-4 text-xs font-mono text-gray-500">
                                    <span className="flex items-center text-white"><Trophy size={12} className="mr-1 text-yellow-500" /> {contest.host}</span>
                                    <span className="flex items-center text-white"><Activity size={12} className="mr-1 text-neon-cyan" /> {contest.level}</span>
                                    <span className="flex items-center">{new Date(contest.date).toLocaleDateString()}</span>
                                </div>
                            </div>

                            <div className="flex items-center gap-2 mt-4 md:mt-0 opacity-0 group-hover:opacity-100 transition-opacity">
                                <button onClick={() => openEditModal(contest)} className="p-2 hover:bg-white/10 text-neon-green rounded transition-colors"><Edit size={18} /></button>
                                <button onClick={() => handleDelete(contest.id)} className="p-2 hover:bg-red-500/10 text-red-500 rounded transition-colors"><Trash2 size={18} /></button>
                            </div>
                        </div>
                    ))}
                    {contests.length === 0 && <div className="text-center py-20 text-gray-500 font-mono">NO ACTIVE AGENT WAR GAMES.</div>}
                </div>
            )}

            {/* Modal */}
            <AnimatePresence>
                {isModalOpen && (
                    <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
                        <motion.div
                            initial={{ opacity: 0 }} onClick={() => setIsModalOpen(false)} className="absolute inset-0 bg-black/80 backdrop-blur-sm"
                        />
                        <motion.div
                            initial={{ opacity: 0, scale: 0.95 }} animate={{ opacity: 1, scale: 1 }}
                            className="relative w-full max-w-2xl bg-[#0a0a0a] border border-white/20 p-8 shadow-2xl z-10"
                        >
                            <button onClick={() => setIsModalOpen(false)} className="absolute top-4 right-4 text-gray-500 hover:text-white"><X size={20} /></button>
                            <h2 className="text-xl font-bold font-sans text-white mb-6">EVENT_CONTROLLER</h2>

                            <form onSubmit={handleSave} className="space-y-4">
                                <div className="grid grid-cols-2 gap-4">
                                    <div>
                                        <label className="label">TITLE</label>
                                        <input className="input" required value={formData.title} onChange={e => setFormData({ ...formData, title: e.target.value })} />
                                    </div>
                                    <div>
                                        <label className="label">HOST</label>
                                        <input className="input" required value={formData.host} onChange={e => setFormData({ ...formData, host: e.target.value })} />
                                    </div>
                                </div>

                                <div className="grid grid-cols-2 gap-4">
                                    <div>
                                        <label className="label">START TIME</label>
                                        <DatePicker
                                            selected={formData.date ? new Date(formData.date) : null}
                                            onChange={(date) => setFormData({ ...formData, date: date ? date.toISOString() : "" })}
                                            showTimeSelect
                                            timeFormat="HH:mm"
                                            timeIntervals={15}
                                            dateFormat="MMMM d, yyyy h:mm aa"
                                            className="input"
                                            calendarClassName="cyberpunk-datepicker shadow-2xl"
                                        />
                                    </div>
                                    <div>
                                        <label className="label">DURATION</label>
                                        <input className="input" value={formData.duration} onChange={e => setFormData({ ...formData, duration: e.target.value })} />
                                    </div>
                                </div>

                                <div className="grid grid-cols-2 gap-4">
                                    <div>
                                        <label className="label">LEVEL</label>
                                        <select className="input" value={formData.level} onChange={e => setFormData({ ...formData, level: e.target.value })}>
                                            <option>EASY</option>
                                            <option>MEDIUM</option>
                                            <option>HARD</option>
                                            <option>INSANE</option>
                                        </select>
                                    </div>
                                    <div>
                                        <label className="label">STATUS</label>
                                        <select className="input" value={formData.status} onChange={e => setFormData({ ...formData, status: e.target.value })}>
                                            <option>UPCOMING</option>
                                            <option>LIVE</option>
                                            <option>PAST</option>
                                        </select>
                                    </div>
                                </div>

                                <div>
                                    <label className="label">DESCRIPTION</label>
                                    <textarea className="input h-20 resize-none" required value={formData.description} onChange={e => setFormData({ ...formData, description: e.target.value })} />
                                </div>

                                <div>
                                    <label className="label">TAGS (Comma separated)</label>
                                    <input className="input" value={formData.tags} onChange={e => setFormData({ ...formData, tags: e.target.value })} placeholder="DP, Greedy" />
                                </div>

                                <div>
                                    <label className="label">CONTEST CODE</label>
                                    <input className="input" value={formData.contestCode} onChange={e => setFormData({ ...formData, contestCode: e.target.value })} placeholder="DV-XXXX-01" />
                                </div>

                                <button type="submit" className="w-full bg-neon-green text-black font-bold font-mono py-3 mt-4 hover:bg-white transition-colors">INITIALIZE EVENT</button>
                            </form>
                        </motion.div>
                    </div>
                )}
            </AnimatePresence>
            <style jsx>{`
                .label { display: block; font-size: 0.65rem; font-family: monospace; color: #9ca3af; margin-bottom: 0.25rem; }
                .input { width: 100%; background: rgba(255,255,255,0.05); border: 1px solid rgba(255,255,255,0.1); padding: 0.5rem; color: white; font-family: sans-serif; outline: none; transition: border-color 0.2s; }
                .input:focus { border-color: #00FF00; }
            `}</style>
        </div>
    );
}

"use client";

import { useState, useEffect } from "react";
import { db } from "@/lib/firebase";
import {
    collection,
    getDocs,
    addDoc,
    updateDoc,
    deleteDoc,
    doc
} from "firebase/firestore";
import {
    Plus,
    Edit,
    Trash2,
    X,
    Save,
    BookOpen,
    Clock,
    Play,
    CheckCircle,
    Shield,
    Database
} from "lucide-react";
import { motion, AnimatePresence } from "framer-motion";

export default function CoursesManager() {
    const [courses, setCourses] = useState([]);
    const [loading, setLoading] = useState(true);
    const [isModalOpen, setIsModalOpen] = useState(false);
    const [currentCourse, setCurrentCourse] = useState(null);
    const [dialog, setDialog] = useState({ show: false, message: "", type: "info" });

    // Initial Form State
    const initialFormState = {
        title: "",
        level: "Beginner", // Beginner, Intermediate, Advanced
        modules: 0,
        duration: "",
        platform: "",
        tree: "AI_CORE",
        description: "",
        thumbnail: "from-gray-800 to-black" // Gradient classes
    };

    const [formData, setFormData] = useState(initialFormState);

    // Fetch Data
    const fetchCourses = async () => {
        setLoading(true);
        try {
            const querySnapshot = await getDocs(collection(db, "courses"));
            const items = querySnapshot.docs.map(doc => ({
                id: doc.id,
                ...doc.data()
            }));
            setCourses(items);
        } catch (error) {
            console.error("Error fetching courses:", error);
        } finally {
            setLoading(false);
        }
    };

    useEffect(() => {
        fetchCourses();
    }, []);

    // Handlers
    const openAddModal = () => {
        setCurrentCourse(null);
        setFormData(initialFormState);
        setIsModalOpen(true);
    };

    const openEditModal = (course) => {
        setCurrentCourse(course);
        setFormData({
            title: course.title,
            level: course.level,
            modules: course.modules,
            duration: course.duration,
            platform: course.platform || "",
            tree: course.tree || "AI_CORE",
            description: course.description,
            thumbnail: course.thumbnail || "from-gray-800 to-black"
        });
        setIsModalOpen(true);
    };

    const handleDelete = async (docId) => {
        if (!confirm("Delete this course?")) return;
        try {
            await deleteDoc(doc(db, "courses", docId));
            setCourses(prev => prev.filter(c => c.id !== docId));
        } catch (error) {
            setDialog({ show: true, message: "Failed to delete: " + error.message, type: "error" });
        }
    };

    const handleSave = async (e) => {
        e.preventDefault();

        const dataToSave = {
            ...formData,
            modules: parseInt(formData.modules) || 0,
            updatedAt: new Date().toISOString()
        };

        try {
            if (currentCourse) {
                const docRef = doc(db, "courses", currentCourse.id);
                await updateDoc(docRef, dataToSave);
                setCourses(prev => prev.map(c => c.id === currentCourse.id ? { ...c, ...dataToSave } : c));
            } else {
                const docRef = await addDoc(collection(db, "courses"), {
                    ...dataToSave,
                    createdAt: new Date().toISOString()
                });
                setCourses(prev => [...prev, { id: docRef.id, ...dataToSave }]);
            }
            setIsModalOpen(false);
        } catch (error) {
            setDialog({ show: true, message: "Failed to save: " + error.message, type: "error" });
        }
    };

    const handleSeed = async () => {
        if (!confirm("WARNING: This will DELETE ALL existing PROMPT_LAB Modules and replace them with REAL educational content. Proceed?")) return;

        const realCourses = [
            // --- AI & MACHINE LEARNING TREE ---
            {
                title: "Introduction to Artificial Intelligence",
                level: "Very Beginner",
                modules: 4,
                duration: "2 Weeks",
                platform: "Coursera",
                tree: "AI_CORE",
                description: "What is AI? History, terminology, and basic concepts. Perfect starting point for complete novices.",
                thumbnail: "from-blue-900 to-black"
            },
            {
                title: "Machine Learning for Everyone",
                level: "Beginner",
                modules: 6,
                duration: "4 Weeks",
                platform: "Kaggle",
                tree: "AI_CORE",
                description: "No-code introduction to ML concepts. Supervised vs Unsupervised learning, regression, and classification.",
                thumbnail: "from-blue-800 to-black"
            },
            {
                title: "Supervised Machine Learning: Regression & Classification",
                level: "Intermediate",
                modules: 12,
                duration: "8 Weeks",
                platform: "Stanford / DeepLearning.AI",
                tree: "AI_CORE",
                description: "Build real ML models. Gradient descent, cost functions, linear & logistic regression from scratch.",
                thumbnail: "from-blue-600 to-black"
            },
            {
                title: "Deep Learning Specialization",
                level: "Advanced",
                modules: 5,
                duration: "3 Months",
                platform: "DeepLearning.AI",
                tree: "AI_CORE",
                description: "Neural Networks, CNNs, RNNs, LSTMs, and Transformers. The state-of-the-art in AI.",
                thumbnail: "from-purple-900 to-black"
            },
            {
                title: "AGI & Consciousness Engineering",
                level: "Ultra-Advanced",
                modules: 10,
                duration: "6 Months",
                platform: "OpenAI Research",
                tree: "AI_CORE",
                description: "Theoretical frameworks for Artificial General Intelligence. Cognitive architectures and consciousness modeling.",
                thumbnail: "from-purple-600 to-black"
            },

            // --- JAVA DEVELOPMENT TREE ---
            {
                title: "Java Programming Basics",
                level: "Very Beginner",
                modules: 5,
                duration: "3 Weeks",
                platform: "Codecademy",
                tree: "DEV_OPS",
                description: "Variables, loops, arrays, and string manipulation. Your first steps into the Java ecosystem.",
                thumbnail: "from-red-900 to-black"
            },
            {
                title: "Object-Oriented Programming in Java",
                level: "Beginner",
                modules: 6,
                duration: "4 Weeks",
                platform: "Udacity",
                tree: "DEV_OPS",
                description: "Classes, Objects, Inheritance, Polymorphism, and Encapsulation. The core of Java design.",
                thumbnail: "from-red-800 to-black"
            },
            {
                title: "Java Collections & Generics",
                level: "Intermediate",
                modules: 4,
