            { title: "Adobe India Hackathon 2025", registrationLink: "https://adobe.com/careers", description: "Innovate with Adobe tools. Open to B.Tech/M.Tech students.", startDate: "2025-07-11T09:00:00.000Z", endDate: "2025-07-13T18:00:00.000Z", registrationDeadline: "2025-06-30T23:59:00.000Z", prizes: "Γé╣1L/mo Internships", tags: ["GenAI", "Creative Cloud"], status: "OPEN", isFeatured: false },
            { title: "Smart India Hackathon 2026", registrationLink: "https://sih.gov.in", description: "World's biggest open innovation model. Solve national problems.", startDate: "2026-06-01T09:00:00.000Z", endDate: "2026-06-03T18:00:00.000Z", registrationDeadline: "2026-05-15T23:59:00.000Z", prizes: "Γé╣1 L per problem", tags: ["GovTech", "Smart City", "Hardware"], status: "UPCOMING", isFeatured: false },
