                                    <span className="flex items-center"><Calendar size={12} className="mr-1" /> {hack.startDate ? new Date(hack.startDate).toLocaleDateString() : hack.date}</span>
                                    <span className="flex items-center"><Trophy size={12} className="mr-1" /> {hack.prizes}</span>
                                    <span className="flex items-center"><Tag size={12} className="mr-1" /> {hack.tags && (Array.isArray(hack.tags) ? hack.tags.join(", ") : hack.tags)}</span>
                                </div>
                            </div>

                            <div className="flex items-center gap-2 mt-4 md:mt-0 opacity-0 group-hover:opacity-100 transition-opacity">
                                <button
                                    onClick={() => openEditModal(hack)}
                                    className="p-2 hover:bg-white/10 text-neon-cyan rounded transition-colors"
                                    title="Edit"
                                >
                                    <Edit size={18} />
                                </button>
                                <button
                                    onClick={() => handleDelete(hack.id)}
                                    className="p-2 hover:bg-red-500/10 text-red-500 rounded transition-colors"
                                    title="Delete"
                                >
                                    <Trash2 size={18} />
                                </button>
                            </div>
                        </div>
                    ))}

                    {sprints.length === 0 && (
                        <div className="text-center py-20 border border-dashed border-white/10 text-gray-500 font-mono">
                            NO ENTRIES FOUND. INITIATE FIRST EVENT.
                        </div>
                    )}
                </div>
            )}

            {/* Modal */}
            <AnimatePresence>
                {isModalOpen && (
                    <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
                        <motion.div
                            initial={{ opacity: 0 }}
                            animate={{ opacity: 1 }}
                            exit={{ opacity: 0 }}
                            onClick={() => setIsModalOpen(false)}
                            className="absolute inset-0 bg-black/80 backdrop-blur-sm"
                        ></motion.div>

                        <motion.div
                            initial={{ opacity: 0, scale: 0.95 }}
                            animate={{ opacity: 1, scale: 1 }}
                            exit={{ opacity: 0, scale: 0.95 }}
                            className="relative w-full max-w-lg bg-[#0a0a0a] border border-white/20 p-8 shadow-2xl z-10 max-h-[90vh] overflow-y-auto"
                        >
                            <button
                                onClick={() => setIsModalOpen(false)}
                                className="absolute top-4 right-4 text-gray-500 hover:text-white"
                            >
                                <X size={20} />
                            </button>

                            <h2 className="text-xl font-bold font-sans text-white mb-6 flex items-center">
                                {currentHackathon ? <Edit className="mr-2 text-neon-cyan" /> : <Plus className="mr-2 text-neon-green" />}
                                {currentHackathon ? "EDIT_PROTOCOL" : "NEW_EVENT_PROTOCOL"}
                            </h2>

                            <form onSubmit={handleSave} className="space-y-4">
                                <div>
                                    <label className="block text-xs font-mono text-gray-400 mb-1">EVENT TITLE</label>
                                    <input
                                        type="text"
                                        required
                                        value={formData.title}
                                        onChange={e => setFormData({ ...formData, title: e.target.value })}
                                        className="w-full bg-white/5 border border-white/10 p-2 text-white focus:border-neon-cyan outline-none font-sans"
                                    />
                                </div>

                                <div className="grid grid-cols-2 gap-4">
                                    <div>
                                        <label className="block text-xs font-mono text-gray-400 mb-1">START DATE</label>
                                        <DatePicker
                                            selected={formData.startDate ? new Date(formData.startDate) : null}
                                            onChange={(date) => setFormData({ ...formData, startDate: date ? date.toISOString() : "" })}
                                            showTimeSelect
                                            timeFormat="HH:mm"
                                            timeIntervals={15}
                                            dateFormat="MM/dd/yyyy h:mm aa"
                                            placeholderText="Start..."
                                            className="w-full bg-white/5 border border-white/10 p-2 text-white focus:border-neon-cyan outline-none font-sans text-sm"
                                        />
                                    </div>
                                    <div>
                                        <label className="block text-xs font-mono text-gray-400 mb-1">END DATE</label>
                                        <DatePicker
                                            selected={formData.endDate ? new Date(formData.endDate) : null}
                                            onChange={(date) => setFormData({ ...formData, endDate: date ? date.toISOString() : "" })}
                                            showTimeSelect
                                            timeFormat="HH:mm"
                                            timeIntervals={15}
                                            dateFormat="MM/dd/yyyy h:mm aa"
                                            placeholderText="End..."
                                            className="w-full bg-white/5 border border-white/10 p-2 text-white focus:border-neon-cyan outline-none font-sans text-sm"
                                        />
                                    </div>
                                </div>

                                <div className="grid grid-cols-2 gap-4">
                                    <div>
                                        <label className="block text-xs font-mono text-gray-400 mb-1">DEADLINE</label>
                                        <DatePicker
                                            selected={formData.registrationDeadline ? new Date(formData.registrationDeadline) : null}
                                            onChange={(date) => setFormData({ ...formData, registrationDeadline: date ? date.toISOString() : "" })}
                                            showTimeSelect
                                            timeFormat="HH:mm"
                                            timeIntervals={15}
                                            dateFormat="MM/dd/yyyy h:mm aa"
                                            placeholderText="Deadline..."
                                            className="w-full bg-white/5 border border-white/10 p-2 text-white focus:border-neon-cyan outline-none font-sans text-sm"
                                        />
                                    </div>
                                    <div>
                                        <label className="block text-xs font-mono text-gray-400 mb-1">STATUS</label>
                                        <select
                                            value={formData.status}
                                            onChange={e => setFormData({ ...formData, status: e.target.value })}
                                            className="w-full bg-white/5 border border-white/10 p-2 text-white focus:border-neon-cyan outline-none font-sans"
                                        >
                                            <option value="UPCOMING">UPCOMING</option>
                                            <option value="OPEN">OPEN / LIVE</option>
                                            <option value="CLOSED">CLOSED</option>
                                            <option value="WAITLIST">WAITLIST</option>
                                        </select>
                                    </div>
                                </div>

                                <div className="flex items-center gap-2 p-3 bg-white/5 border border-white/10 rounded cursor-pointer" onClick={() => setFormData(prev => ({ ...prev, isFeatured: !prev.isFeatured }))}>
                                    <div className={`w-4 h-4 border flex items-center justify-center transition-colors ${formData.isFeatured ? 'bg-neon-green border-neon-green' : 'border-gray-500'}`}>
                                        {formData.isFeatured && <div className="w-2 h-2 bg-black"></div>}
                                    </div>
                                    <span className="text-sm font-mono text-gray-300">FEATURE_ON_HOMEPAGE</span>
                                </div>

                                <div>
                                    <label className="block text-xs font-mono text-gray-400 mb-1">PRIZE POOL</label>
                                    <input
                                        type="text"
                                        required
                                        placeholder="$10,000 USD"
                                        value={formData.prizes}
                                        onChange={e => setFormData({ ...formData, prizes: e.target.value })}
                                        className="w-full bg-white/5 border border-white/10 p-2 text-white focus:border-neon-cyan outline-none font-sans"
                                    />
                                </div>

                                <div>
                                    <label className="block text-xs font-mono text-gray-400 mb-1">TAGS (comma separated)</label>
                                    <input
                                        type="text"
                                        placeholder="AI, Blockchain, Python"
                                        value={formData.tags}
                                        onChange={e => setFormData({ ...formData, tags: e.target.value })}
                                        className="w-full bg-white/5 border border-white/10 p-2 text-white focus:border-neon-cyan outline-none font-sans"
                                    />
                                </div>

                                <div>
                                    <label className="block text-xs font-mono text-gray-400 mb-1">REGISTRATION LINK (Optional if internal)</label>
                                    <input
                                        type="text"
                                        placeholder="https://..."
                                        value={formData.registrationLink}
                                        onChange={e => setFormData({ ...formData, registrationLink: e.target.value })}
                                        className="w-full bg-white/5 border border-white/10 p-2 text-white focus:border-neon-cyan outline-none font-sans"
                                    />
                                </div>

                                <div>
                                    <label className="block text-xs font-mono text-gray-400 mb-1">DESCRIPTION</label>
                                    <textarea
                                        rows="3"
                                        required
                                        value={formData.description}
                                        onChange={e => setFormData({ ...formData, description: e.target.value })}
                                        className="w-full bg-white/5 border border-white/10 p-2 text-white focus:border-neon-cyan outline-none font-sans resize-none"
                                    ></textarea>
                                </div>

                                <button
                                    type="submit"
                                    className="w-full bg-white text-black font-bold font-mono py-3 mt-4 hover:bg-neon-cyan transition-colors flex justify-center items-center"
                                >
                                    <Save size={16} className="mr-2" /> SAVE_TO_DATABASE
                                </button>
                            </form>
                        </motion.div>
                    </div>
                )}
            </AnimatePresence>
        </div>
    );
}

"use client";

import { useState, useEffect } from "react";
import { auth } from "@/lib/firebase";
import { onAuthStateChanged, signOut } from "firebase/auth";
import { useRouter, usePathname } from "next/navigation";
import Link from "next/link";
import {
    LayoutDashboard,
    Trophy,
    BookOpen,
    LogOut,
    Menu,
    X,
    Users,
    Activity,
    ArrowLeft,
    Briefcase,
    Shield,
    CreditCard,
    Database,
    Gamepad,
    Layers
} from "lucide-react";
import { motion, AnimatePresence } from "framer-motion";

export default function AdminLayout({ children }) {
    const [user, setUser] = useState(null);
    const [loading, setLoading] = useState(true);
    const [isSidebarOpen, setIsSidebarOpen] = useState(true);
    const router = useRouter();
    const pathname = usePathname();

    useEffect(() => {
        const unsubscribe = onAuthStateChanged(auth, (authUser) => {
            if (!authUser) {
                router.push("/login");
            } else if (!authUser.email.includes("admin")) {
                router.push("/"); // Redirect non-admins
            } else {
                setUser(authUser);
            }
            setLoading(false);
        });

        return () => unsubscribe();
    }, [router]);

    const handleLogout = async () => {
        await signOut(auth);
        router.push("/login");
    };

    if (loading) return (
        <div className="min-h-screen bg-black flex items-center justify-center text-neon-cyan font-mono animate-pulse">
            INITIALIZING_ADMIN_PROTOCOL...
        </div>
    );

    if (!user) return null;

    const navItems = [
        { name: "DASHBOARD", href: "/admin", icon: LayoutDashboard },
        { name: "FEATURES", href: "/admin/features", icon: Layers },
        { name: "CLIENT OPS", href: "/admin/requirements", icon: Briefcase },
        { name: "SQUAD OPS", href: "/admin/architects", icon: Shield },
        { name: "USER BASE", href: "/admin/users", icon: Users },
        { name: "FINANCE", href: "/admin/finance", icon: CreditCard },
        { name: "AGENT SPRINTS", href: "/admin/hackathons", icon: Trophy },
        { name: "PERFORMANCE LOGS", href: "/admin/postmortems", icon: Activity },
        { name: "PROMPT LAB", href: "/admin/courses", icon: BookOpen },
        { name: "WARGAMES", href: "/admin/contests", icon: Gamepad },
        { name: "SYSTEM", href: "/admin/settings", icon: Database },
    ];

    return (
        <div className="min-h-screen bg-background text-foreground flex relative overflow-hidden">
            {/* Mobile Backdrop */}
            <AnimatePresence>
                {isSidebarOpen && (
                    <motion.div
                        initial={{ opacity: 0 }}
                        animate={{ opacity: 1 }}
                        exit={{ opacity: 0 }}
                        onClick={() => setIsSidebarOpen(false)}
                        className="fixed inset-0 bg-black/60 backdrop-blur-sm z-30 lg:hidden"
                    />
                )}
            </AnimatePresence>

            {/* Sidebar */}
            <motion.aside
                initial={false}
                animate={{
                    x: isSidebarOpen ? 0 : "-100%",
                    width: "240px",
                    opacity: 1
                }}
                transition={{ type: "spring", damping: 25, stiffness: 200 }}
                className={`
                    fixed top-0 left-0 h-[100dvh] z-40 bg-card-bg border-r border-border flex flex-col
                    lg:relative lg:translate-x-0 lg:h-screen lg:flex
                    ${!isSidebarOpen ? "hidden lg:flex lg:w-0 lg:border-none lg:opacity-0" : ""}
                `}
                style={{ width: 240 }} // Force width for motion
            >
                <div className="p-6 flex-shrink-0">
                    <Link href="/" className="block group">
                        <h1 className="text-xl font-bold font-sans tracking-widest text-neon-cyan mb-1 group-hover:opacity-80 transition-opacity">
                            DEVERT<span className="text-foreground">.IN</span>
                        </h1>
                        <p className="text-[10px] font-mono text-muted-foreground group-hover:text-neon-green transition-colors flex items-center gap-2">
                            <ArrowLeft size={10} /> RETURN_HOME
                        </p>
                    </Link>
                </div>

                <nav className="px-4 space-y-1 flex-1 overflow-y-auto custom-scrollbar">
                    {navItems.map((item) => {
                        const Icon = item.icon;
                        const isActive = pathname === item.href;

                        return (
                            <Link
                                key={item.href}
                                href={item.href}
                                onClick={() => {
                                    if (window.innerWidth < 1024) setIsSidebarOpen(false);
                                }}
                                className={`flex items-center space-x-3 px-4 py-3 rounded font-mono text-sm transition-all duration-300 ${isActive
                                    ? "bg-neon-cyan/10 text-neon-cyan border border-neon-cyan/50 shadow-[0_0_10px_rgba(34,211,238,0.2)]"
                                    : "text-muted-foreground hover:text-foreground hover:bg-white/5"
                                    }`}
                            >
                                <Icon size={18} />
                                <span className="tracking-wide">{item.name}</span>
                            </Link>
                        );
                    })}
                </nav>

                <div className="p-4 bg-card-bg border-t border-border flex-shrink-0">
                    <button
                        onClick={handleLogout}
                        className="w-full flex items-center justify-center space-x-3 px-4 py-3 rounded font-mono text-sm text-red-500 hover:bg-red-500/10 hover:text-red-400 transition-colors border border-transparent hover:border-red-500/30"
                    >
                        <LogOut size={18} />
                        <span>TERMINATE</span>
                    </button>
                    <div className="mt-2 text-[10px] font-mono text-muted-foreground text-center truncate">
                        {user.email}
                    </div>
                </div>
            </motion.aside>

            {/* Main Content */}
            <main className="flex-1 flex flex-col h-screen overflow-hidden relative">
                {/* Top Bar (Mobile Toggle) */}
                <header className="h-16 flex items-center justify-between px-6 border-b border-border bg-background/50 backdrop-blur-sm lg:hidden">
                    <button
                        onClick={() => setIsSidebarOpen(true)}
                        className="text-gray-400 hover:text-white transition-colors"
                    >
                        <Menu size={24} />
                    </button>
                    <div className="font-mono text-xs text-neon-cyan animate-pulse">
                        SECURE_CONNECTION
                    </div>
                </header>

                <div className="flex-1 overflow-auto p-4 md:p-10 relative">
                    {/* Background GFX */}
                    <div className="absolute inset-0 grid-bg opacity-10 pointer-events-none fixed"></div>

                    <motion.div
                        initial={{ opacity: 0, y: 20 }}
                        animate={{ opacity: 1, y: 0 }}
                        transition={{ duration: 0.4 }}
                        className="relative z-10"
                    >
                        {children}
                    </motion.div>
                </div>
            </main>
        </div>
    );
}

"use client";

import { useEffect, useState } from "react";
import { db } from "@/lib/firebase";
import { collection, getDocs, orderBy, query, limit, where, Timestamp } from "firebase/firestore";
import { Trophy, BookOpen, Users, Activity, ExternalLink, Zap, Target, TrendingUp, Clock, DollarSign } from "lucide-react";
import Link from "next/link";
import { LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip as RechartsTooltip, ResponsiveContainer, BarChart, Bar, AreaChart, Area } from 'recharts';

export default function AdminDashboard() {
    const [stats, setStats] = useState({
        hackathons: 0,
        courses: 0,
        postmortems: 0,
        bounties: 0,
        contests: 0,
        totalUsers: 0,
        activeUsers24h: 0,
    });
    const [userGrowthData, setUserGrowthData] = useState([]);
    const [recentActivity, setRecentActivity] = useState([]);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        const fetchStats = async () => {
            try {
                // Fetch Collections
                const [hacks, courses, pms, bounties, contests, users] = await Promise.all([
                    getDocs(collection(db, "hackathons")),
                    getDocs(collection(db, "courses")),
                    getDocs(collection(db, "postmortems")),
                    getDocs(collection(db, "bounties")),
                    getDocs(collection(db, "contests")),
                    getDocs(collection(db, "users")),
                ]);

                // Calculate User Stats
                const now = new Date();
                const oneDayAgo = new Date(now.getTime() - (24 * 60 * 60 * 1000));

                let active24h = 0;
                const growthMap = {};

                users.docs.forEach(doc => {
                    const data = doc.data();

                    // Check active
                    let lastLoginDate = null;
                    if (data.lastLogin && typeof data.lastLogin.toDate === 'function') {
                        lastLoginDate = data.lastLogin.toDate();
                    } else if (data.lastLogin) {
                        lastLoginDate = new Date(data.lastLogin);
                    }

                    if (lastLoginDate && lastLoginDate > oneDayAgo) active24h++;

                    // User Growth Data
                    let createdAtDate = null;
                    if (data.createdAt && typeof data.createdAt.toDate === 'function') {
                        createdAtDate = data.createdAt.toDate();
                    } else if (data.createdAt) {
                        createdAtDate = new Date(data.createdAt);
                    }

                    if (createdAtDate) {
                        const dateKey = createdAtDate.toLocaleDateString('en-US', { month: 'short', day: 'numeric' });
                        growthMap[dateKey] = (growthMap[dateKey] || 0) + 1;
                    }
                });

                // Format growth data for Recharts
                const formattedGrowthData = Object.entries(growthMap)
                    .map(([date, count]) => ({ date, users: count }))
                    .sort((a, b) => new Date(a.date) - new Date(b.date))
                    .slice(-7); // Last 7 days/entries

                setStats({
                    hackathons: hacks.size,
                    courses: courses.size,
                    postmortems: pms.size,
                    bounties: bounties.size,
                    contests: contests.size,
                    totalUsers: users.size,
                    activeUsers24h: active24h,
                });

                setUserGrowthData(formattedGrowthData);
                setLoading(false);
            } catch (error) {
                console.error("Error fetching admin stats:", error);
                setLoading(false);
            }
        };

        fetchStats();
    }, []);

    const CustomTooltip = ({ active, payload, label }) => {
        if (active && payload && payload.length) {
            return (
                <div className="bg-card-bg border border-border p-2 rounded shadow-xl text-xs font-mono">
                    <p className="text-gray-400">{label}</p>
                    <p className="text-neon-cyan font-bold">{payload[0].value} Users</p>
                </div>
            );
        }
        return null;
    };

    const StatCard = ({ title, value, icon: Icon, color, href, subtitle }) => (
        <Link href={href}>
            <div className={`h-full p-6 bg-card-bg border border-border hover:border-${color} group transition-all duration-300 cursor-pointer relative overflow-hidden flex flex-col justify-between`}>
                <div className={`absolute top-0 right-0 p-3 opacity-10 group-hover:opacity-20 transition-opacity text-${color}`}>
                    <Icon size={64} />
                </div>
                <div className="relative z-10">
                    <div className={`text-${color} mb-2`}>
                        <Icon size={24} />
                    </div>
                    <div className="text-3xl font-bold font-sans mb-1 text-foreground">{value}</div>
                    <div className="text-xs font-mono text-gray-400 uppercase tracking-widest">{title}</div>
                    {subtitle && <div className="text-xs font-mono text-gray-500 mt-2">{subtitle}</div>}
                </div>
                <div className={`absolute bottom-0 left-0 h-1 bg-${color} w-0 group-hover:w-full transition-all duration-500`}></div>
            </div>
        </Link>
    );

    return (
        <div className="space-y-8">
            <div className="flex justify-between items-end">
                <div>
                    <h2 className="text-4xl font-bold font-sans text-foreground mb-2">COMMAND_CENTER</h2>
                    <p className="font-mono text-sm text-gray-500">Welcome back, Administrator. System status: <span className="text-neon-green">OPTIMAL</span>.</p>
                </div>
                <div className="flex gap-4">
                    <div className="font-mono text-xs text-neon-cyan border border-neon-cyan/30 px-3 py-1 bg-neon-cyan/5 flex items-center gap-2">
                        <span className="relative flex h-2 w-2">
                            <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-neon-cyan opacity-75"></span>
                            <span className="relative inline-flex rounded-full h-2 w-2 bg-neon-cyan"></span>
                        </span>
                        LIVE DATA FEED
                    </div>
                </div>
            </div>

            {/* Quick Stats Grid */}
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
                <StatCard
                    title="Total Users"
                    value={loading ? "-" : stats.totalUsers}
                    icon={Users}
                    color="neon-blue" // Using custom tailwind color if available or standard blue-500
                    href="/admin/users"
                    subtitle={`${stats.activeUsers24h} active in last 24h`}
                />
                <StatCard
                    title="Active Agent Sprints"
                    value={loading ? "-" : stats.hackathons}
                    icon={Trophy}
                    color="neon-green"
                    href="/admin/hackathons"
                />
                <StatCard
                    title="Open Bounties"
                    value={loading ? "-" : stats.bounties}
                    icon={Zap}
                    color="yellow-500"
                    href="/admin/bounties"
                />
                <StatCard
                    title="Total Revenue"
                    value={loading ? "-" : "$0.00"}
                    icon={DollarSign}
                    color="neon-purple"
                    href="/admin/finance"
                    subtitle="0 pending payouts"
                />
            </div>

            {/* Analytics Section */}
            <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
                {/* User Growth Chart */}
                <div className="lg:col-span-2 bg-card-bg border border-border p-6 rounded-none relative">
                    <h3 className="text-lg font-bold font-sans mb-6 flex items-center text-foreground">
                        <TrendingUp className="mr-2 text-neon-cyan" size={20} />
                        USER_ACQUISITION_TREND
                    </h3>
                    <div className="h-[300px] w-full">
                        {loading ? (
                            <div className="h-full w-full flex items-center justify-center text-gray-600 font-mono animate-pulse">LOADING ANALYTICS...</div>
                        ) : (
                            <ResponsiveContainer width="100%" height="100%">
                                <AreaChart data={userGrowthData}>
                                    <defs>
                                        <linearGradient id="colorUsers" x1="0" y1="0" x2="0" y2="1">
                                            <stop offset="5%" stopColor="#00f3ff" stopOpacity={0.3} />
                                            <stop offset="95%" stopColor="#00f3ff" stopOpacity={0} />
                                        </linearGradient>
                                    </defs>
                                    <CartesianGrid strokeDasharray="3 3" stroke="#ffffff10" />
                                    <XAxis dataKey="date" stroke="#6b7280" tick={{ fill: '#6b7280', fontSize: 12, fontFamily: 'monospace' }} />
                                    <YAxis stroke="#6b7280" tick={{ fill: '#6b7280', fontSize: 12, fontFamily: 'monospace' }} />
                                    <RechartsTooltip content={<CustomTooltip />} />
                                    <Area type="monotone" dataKey="users" stroke="#00f3ff" fillOpacity={1} fill="url(#colorUsers)" />
                                </AreaChart>
                            </ResponsiveContainer>
                        )}
                    </div>
                </div>

                {/* Engagement / Login Time Distribution (Mocked for now as real time logs need backend) */}
                <div className="bg-card-bg border border-border p-6 rounded-none">
                    <h3 className="text-lg font-bold font-sans mb-6 flex items-center text-foreground">
                        <Clock className="mr-2 text-neon-green" size={20} />
                        PEAK_ACTIVITY_HOURS
                    </h3>
                    <div className="h-[300px] w-full">
                        {/* Mock data for visualization since granular hourly logs aren't stored yet */}
                        <ResponsiveContainer width="100%" height="100%">
                            <BarChart data={[
                                { name: '00-04', val: 12 }, { name: '04-08', val: 5 },
                                { name: '08-12', val: 35 }, { name: '12-16', val: 58 },
                                { name: '16-20', val: 45 }, { name: '20-24', val: 22 }
                            ]}>
                                <CartesianGrid strokeDasharray="3 3" stroke="#ffffff10" vertical={false} />
                                <XAxis dataKey="name" stroke="#6b7280" tick={{ fill: '#6b7280', fontSize: 10, fontFamily: 'monospace' }} />
                                <RechartsTooltip
                                    contentStyle={{ backgroundColor: '#000', borderColor: '#333' }}
                                    itemStyle={{ color: '#0f0' }}
                                />
                                <Bar dataKey="val" fill="#00ff9d" radius={[4, 4, 0, 0]} />
                            </BarChart>
                        </ResponsiveContainer>
                        <p className="text-center text-xs text-gray-600 font-mono mt-2">*Based on server request density</p>
                    </div>
                </div>
            </div>

            {/* Quick Actions Footer */}
            <div className="border border-white/10 p-4 bg-white/[0.02] flex flex-wrap gap-4 justify-between items-center">
                <div className="text-xs font-mono text-gray-500">
                    SYSTEM_VERSION: v2.4.0-RC1
                </div>
                <div className="flex gap-3">
                    <Link href="/admin/users" className="text-xs font-mono text-neon-cyan hover:underline">MANAGE_USERS</Link>
                    <span className="text-gray-700">|</span>
                    <Link href="/admin/finance" className="text-xs font-mono text-neon-cyan hover:underline">VIEW_LEDGER</Link>
                </div>
            </div>
        </div>
    );
}

"use client";

import { useState, useEffect } from "react";
import { db } from "@/lib/firebase";
import {
    collection,
    getDocs,
    addDoc,
    updateDoc,
    deleteDoc,
    doc
} from "firebase/firestore";
import {
    Plus,
    Edit,
    Trash2,
    X,
    Save,
    Activity,
    CheckCircle,
    XCircle,
    Copy,
    Shield,
    Database
} from "lucide-react";
import { motion, AnimatePresence } from "framer-motion";
import DatePicker from "react-datepicker";
import "react-datepicker/dist/react-datepicker.css";

export default function PostmortemsManager() {
    const [postmortems, setPostmortems] = useState([]);
    const [loading, setLoading] = useState(true);
    const [isModalOpen, setIsModalOpen] = useState(false);
    const [currentPm, setCurrentPm] = useState(null);
    const [dialog, setDialog] = useState({ show: false, message: "", type: "info" });

    // Initial Form State
    const initialFormState = {
        title: "",
        id: "", // Mission ID
        status: "LOST", // LOST or WON
        teamSize: 4,
        rank: "",
        stack: "", // Comma separated string for input
        whyLost: "", // PRIMARY_OUTCOME_FACTOR
        whyWon: "", // PRIMARY_OUTCOME_FACTOR
        winningSignals: "", // Newline separated
        criticalMistakes: "", // Newline separated
        patchIfRedeployed: "", // Newline separated
        verdict: "",
        date: new Date().toISOString().split('T')[0]
    };

    const [formData, setFormData] = useState(initialFormState);

    // Fetch Data
    const fetchPostmortems = async () => {
        setLoading(true);
        try {
            const querySnapshot = await getDocs(collection(db, "postmortems"));
            const items = querySnapshot.docs.map(doc => ({
                docId: doc.id,
                ...doc.data()
            }));
            setPostmortems(items);
        } catch (error) {
            console.error("Error fetching postmortems:", error);
        } finally {
            setLoading(false);
        }
    };

    useEffect(() => {
        fetchPostmortems();
    }, []);

    // Handlers
    const openAddModal = () => {
        setCurrentPm(null);
        setFormData(initialFormState);
        setIsModalOpen(true);
    };

    const openEditModal = (pm) => {
        setCurrentPm(pm);
        setFormData({
            title: pm.title,
            id: pm.id,
            status: pm.status,
            teamSize: pm.teamSize,
            rank: pm.rank,
            stack: pm.stack ? pm.stack.join(", ") : "",
            whyLost: pm.whyLost || "",
            whyWon: pm.whyWon || "",
            winningSignals: pm.winningSignals ? pm.winningSignals.join("\n") : "",
            criticalMistakes: pm.criticalMistakes ? pm.criticalMistakes.join("\n") : "",
            patchIfRedeployed: pm.patchIfRedeployed ? pm.patchIfRedeployed.join("\n") : "",
            verdict: pm.verdict,
            date: pm.date
        });
        setIsModalOpen(true);
    };

    const handleDelete = async (docId) => {
        if (!confirm("Delete this performance record?")) return;
        try {
            await deleteDoc(doc(db, "postmortems", docId));
            setPostmortems(prev => prev.filter(p => p.docId !== docId));
        } catch (error) {
            setDialog({ show: true, message: "Failed to delete: " + error.message, type: "error" });
        }
    };

    const handleSave = async (e) => {
        e.preventDefault();

        // Process arrays
        const processArray = (str) => str.split('\n').map(s => s.trim()).filter(s => s);
        const processTags = (str) => str.split(',').map(s => s.trim()).filter(s => s);

        const dataToSave = {
            ...formData,
            stack: processTags(formData.stack),
            winningSignals: processArray(formData.winningSignals),
            criticalMistakes: processArray(formData.criticalMistakes),
            patchIfRedeployed: processArray(formData.patchIfRedeployed),
            teamSize: parseInt(formData.teamSize) || 0,
            updatedAt: new Date().toISOString()
        };

        // Clean up empty fields based on status
        if (dataToSave.status === "WON") {
            delete dataToSave.whyLost;
            delete dataToSave.criticalMistakes;
            // Ensure won fields exist
            if (!dataToSave.whyWon) dataToSave.whyWon = "N/A";
        } else {
            delete dataToSave.whyWon;
            delete dataToSave.winningSignals;
            // Ensure lost fields exist
            if (!dataToSave.whyLost) dataToSave.whyLost = "N/A";
        }

        try {
            if (currentPm) {
                const docRef = doc(db, "postmortems", currentPm.docId);
                await updateDoc(docRef, dataToSave);
                setPostmortems(prev => prev.map(p => p.docId === currentPm.docId ? { ...p, ...dataToSave } : p));
            } else {
                const docRef = await addDoc(collection(db, "postmortems"), {
                    ...dataToSave,
                    createdAt: new Date().toISOString()
                });
                setPostmortems(prev => [...prev, { docId: docRef.id, ...dataToSave }]);
            }
            setIsModalOpen(false);
        } catch (error) {
            setDialog({ show: true, message: "Failed to save: " + error.message, type: "error" });
        }
    };

    const handleSeed = async () => {
        if (!confirm("WARNING: This will DELETE ALL existing PERFORMANCE LOGS and replace them with REAL EXAMPLES. Proceed?")) return;

        const realPostmortems = [
            {
                title: "ETHIndia 2025",
                id: "ETH-2025-01",
                status: "WON",
                teamSize: 4,
                rank: "Top 10",
                stack: ["Solidity", "Next.js", "Hardhat"],
                whyWon: "Flawless minimal demo focused on one core feature.",
                winningSignals: ["Pitch was rehearsed 50 times", "UI was fully polished", "Contract was verified"],
                date: "2025-12-04",
                verdict: "Victory through simplicity."
            },
            {
                title: "Smart India Hackathon 2024",
                id: "SIH-2024-FN",
                status: "LOST",
                teamSize: 6,
                rank: "Finalist",
                stack: ["Django", "React", "PostgreSQL"],
                whyLost: "Backend server crashed during live demo due to unhandled exception.",
                criticalMistakes: ["No offline backup video", "Last minute merge conflict", "Spaghetti code"],
                patchIfRedeployed: ["Dockerize everything", "Record backup demo"],
                date: "2024-08-20",
                verdict: "Hard lesson in reliability."
            },
            {
                title: "HackMIT",
                id: "MIT-2025",
                status: "WON",
                teamSize: 3,
                rank: "Track Winner",
                stack: ["Python", "TensorFlow", "FastAPI"],
                whyWon: "Solved a genuine user pain point with a novel AI approach.",
                winningSignals: ["Judges loved the problem statement", "Novel algorithm"],
                date: "2025-09-15",
                verdict: "Innovation wins over complexity."
            }
        ];

        setLoading(true);
        try {
            // 1. Clear existing data
            const snapshot = await getDocs(collection(db, "postmortems"));
            const deletePromises = snapshot.docs.map(d => deleteDoc(doc(db, "postmortems", d.id)));
            await Promise.all(deletePromises);

            // 2. Add new data
            const addPromises = realPostmortems.map(pm =>
                addDoc(collection(db, "postmortems"), {
                    ...pm,
                    createdAt: new Date().toISOString()
                })
            );
            await Promise.all(addPromises);
            setDialog({ show: true, message: "Performance Archives Refreshed.", type: "success" });
            fetchPostmortems();
        } catch (error) {
            console.error("Seeding failed:", error);
            setDialog({ show: true, message: "Seeding failed: " + error.message, type: "error" });
        } finally {
            setLoading(false);
        }
    };

    return (
        <div className="relative min-h-[80vh]">
            {/* Dialog Modal */}
            {dialog.show && (
                <div className="fixed inset-0 z-[60] flex items-center justify-center p-4 bg-black/80 backdrop-blur-sm animate-in fade-in duration-200">
                    <div className="bg-[#0a0a0a] border border-white/10 p-8 max-w-md w-full relative shadow-2xl flex flex-col items-center text-center">
                        <div className={`mb-4 p-4 rounded-full ${dialog.type === 'error' ? 'bg-red-500/10 text-red-500' : 'bg-neon-green/10 text-neon-green'}`}>
                            {dialog.type === 'error' ? <Shield size={32} /> : <CheckCircle size={32} />}
                        </div>
                        <h3 className="text-xl font-bold font-sans text-white mb-2">{dialog.type === 'error' ? 'SYSTEM_ERROR' : 'OPERATION_COMPLETE'}</h3>
                        <p className="font-mono text-sm text-gray-400 mb-6">{dialog.message}</p>
                        <button
                            onClick={() => setDialog({ ...dialog, show: false })}
                            className="w-full bg-white/10 hover:bg-white/20 text-white font-mono py-2 text-sm uppercase tracking-wider transition-colors"
                        >
                            CLOSE_DIALOG
                        </button>
                    </div>
                </div>
            )}

            <div className="flex justify-between items-center mb-8">
                <div>
                    <h1 className="text-3xl font-bold font-sans text-white">PERFORMANCE_LOGS</h1>
                    <p className="font-mono text-xs text-gray-500">Analyze agent deployment success patterns.</p>
                </div>
                <div className="flex gap-2">
                    <button
                        onClick={handleSeed}
                        className="bg-white/10 border border-white/20 text-white px-4 py-2 font-bold font-mono text-sm flex items-center hover:bg-white hover:text-black transition-all"
                    >
                        <Database size={16} className="mr-2" /> SEED_REAL_DATA
                    </button>
                    <button
                        onClick={openAddModal}
                        className="bg-neon-cyan text-black px-4 py-2 font-bold font-mono text-sm flex items-center hover:bg-white transition-colors"
                    >
                        <Plus size={16} className="mr-2" /> NEW_ANALYSIS
                    </button>
                </div>
            </div>

            {loading ? (
                <div className="text-neon-cyan font-mono animate-pulse">Retrieving archived logs...</div>
            ) : (
                <div className="grid grid-cols-1 gap-4">
                    {postmortems.map((pm) => (
                        <div
                            key={pm.docId}
                            className={`bg-black/40 border border-white/10 p-6 hover:border-white/30 transition-colors group flex justify-between items-center ${pm.status === 'WON' ? 'border-l-4 border-l-neon-green' : 'border-l-4 border-l-red-500'}`}
                        >
                            <div className="flex-1">
                                <div className="flex items-center gap-3 mb-1">
                                    <span className={`font-mono text-xs font-bold ${pm.status === 'WON' ? 'text-neon-green' : 'text-red-500'}`}>
                                        {pm.status}
                                    </span>
                                    <span className="text-gray-600 font-mono text-xs">|</span>
                                    <span className="font-mono text-xs text-gray-400">{pm.id}</span>
                                </div>
                                <h3 className="text-lg font-bold font-sans text-white">{pm.title}</h3>
                                <div className="mt-2 text-xs font-mono text-gray-500 flex gap-4">
                                    <span>Rank: {pm.rank}</span>
                                    <span>Team: {pm.teamSize}</span>
                                    <span>Verdt: {pm.verdict && pm.verdict.substring(0, 30)}...</span>
                                </div>
                            </div>

                            <div className="flex gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                                <button onClick={() => openEditModal(pm)} className="p-2 hover:bg-white/10 text-neon-cyan rounded"><Edit size={18} /></button>
                                <button onClick={() => handleDelete(pm.docId)} className="p-2 hover:bg-red-500/10 text-red-500 rounded"><Trash2 size={18} /></button>
                            </div>
                        </div>
                    ))}
                    {postmortems.length === 0 && <div className="text-gray-500 font-mono text-center py-10">NO LOGS FOUND</div>}
                </div>
            )}

            {/* Modal */}
            <AnimatePresence>
                {isModalOpen && (
                    <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
                        <motion.div
                            initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}
                            onClick={() => setIsModalOpen(false)} className="absolute inset-0 bg-black/80 backdrop-blur-sm"
                        />
                        <motion.div
                            initial={{ opacity: 0, scale: 0.95 }} animate={{ opacity: 1, scale: 1 }} exit={{ opacity: 0, scale: 0.95 }}
                            className="relative w-full max-w-2xl bg-[#0a0a0a] border border-white/20 p-8 shadow-2xl z-10 max-h-[90vh] overflow-y-auto"
                        >
                            <button onClick={() => setIsModalOpen(false)} className="absolute top-4 right-4 text-gray-500 hover:text-white"><X size={20} /></button>
                            <h2 className="text-xl font-bold font-sans text-white mb-6">PERFORMANCE_LOG_ENTRY</h2>

                            <form onSubmit={handleSave} className="space-y-4">
                                <div className="grid grid-cols-2 gap-4">
                                    <div>
                                        <label className="label">MISSION ID</label>
                                        <input className="input" required value={formData.id} onChange={e => setFormData({ ...formData, id: e.target.value })} placeholder="GAI-2026" />
                                    </div>
                                    <div>
                                        <label className="label">STATUS</label>
                                        <select className="input" value={formData.status} onChange={e => setFormData({ ...formData, status: e.target.value })}>
                                            <option value="LOST">LOST</option>
                                            <option value="WON">WON</option>
                                        </select>
                                    </div>
                                </div>

                                <div>
                                    <label className="label">EVENT TITLE</label>
                                    <input className="input" required value={formData.title} onChange={e => setFormData({ ...formData, title: e.target.value })} />
                                </div>

                                <div className="grid grid-cols-3 gap-4">
                                    <div>
                                        <label className="label">TEAM SIZE</label>
                                        <input type="number" className="input" required value={formData.teamSize} onChange={e => setFormData({ ...formData, teamSize: e.target.value })} />
                                    </div>
                                    <div>
                                        <label className="label">RANK / SCORE</label>
                                        <input className="input" required value={formData.rank} onChange={e => setFormData({ ...formData, rank: e.target.value })} placeholder="42/1200" />
                                    </div>
                                    <div>
                                        <label className="label">DATE</label>
                                        <DatePicker
                                            selected={formData.date ? new Date(formData.date) : null}
                                            onChange={(date) => setFormData({ ...formData, date: date ? date.toISOString().split('T')[0] : "" })}
                                            dateFormat="yyyy-MM-dd"
                                            placeholderText="MISSION_DATE"
                                            className="input w-full"
                                            calendarClassName="cyberpunk-datepicker shadow-2xl"
                                        />
                                    </div>
                                </div>

                                <div>
                                    <label className="label">TECH STACK (Comma separated)</label>
                                    <input className="input" value={formData.stack} onChange={e => setFormData({ ...formData, stack: e.target.value })} placeholder="React, Solidity, Python" />
                                </div>

                                <div className="border-t border-white/10 pt-4">
                                    <label className="label flex items-center gap-2">
                                        <Activity size={12} />
                                        {formData.status === 'WON' ? 'PRIMARY WIN FACTOR' : 'PRIMARY OUTCOME FACTOR (Why we lost)'}
                                    </label>
                                    <textarea
                                        className="input h-20 resize-none"
                                        required
                                        value={formData.status === 'WON' ? formData.whyWon : formData.whyLost}
                                        onChange={e => setFormData({
                                            ...formData,
                                            [formData.status === 'WON' ? 'whyWon' : 'whyLost']: e.target.value
                                        })}
                                    />
                                </div>

                                <div className="grid grid-cols-2 gap-4">
                                    <div>
                                        <label className="label">
                                            {formData.status === 'WON' ? 'WINNING SIGNALS' : 'CRITICAL MISTAKES'} (One per line)
                                        </label>
                                        <textarea
                                            className="input h-32 resize-none font-mono text-xs"
                                            value={formData.status === 'WON' ? formData.winningSignals : formData.criticalMistakes}
                                            onChange={e => setFormData({
                                                ...formData,
                                                [formData.status === 'WON' ? 'winningSignals' : 'criticalMistakes']: e.target.value
                                            })}
                                            placeholder="- Item 1&#10;- Item 2"
                                        />
                                    </div>
                                    <div>
                                        <label className="label">PATCH IF REDEPLOYED (One per line)</label>
                                        <textarea
                                            className="input h-32 resize-none font-mono text-xs"
                                            value={formData.patchIfRedeployed}
                                            onChange={e => setFormData({ ...formData, patchIfRedeployed: e.target.value })}
                                            placeholder="- Cut features&#10;- Better demo"
                                        />
                                    </div>
                                </div>

                                <div>
                                    <label className="label">FINAL VERDICT</label>
                                    <input className="input" required value={formData.verdict} onChange={e => setFormData({ ...formData, verdict: e.target.value })} />
                                </div>

                                <button type="submit" className="btn-primary w-full mt-4">SAVE RECORD</button>
                            </form>
                        </motion.div>
                    </div>
                )}
            </AnimatePresence>

            <style jsx>{`
                .label { display: block; font-size: 0.65rem; font-family: monospace; color: #9ca3af; margin-bottom: 0.25rem; }
                .input { width: 100%; background: rgba(255,255,255,0.05); border: 1px solid rgba(255,255,255,0.1); padding: 0.5rem; color: white; font-family: sans-serif; outline: none; transition: border-color 0.2s; }
                .input:focus { border-color: #00FFFF; }
                .btn-primary { background: #00FFFF; color: black; font-weight: bold; font-family: monospace; padding: 0.75rem; text-transform: uppercase; transition: all 0.2s; }
                .btn-primary:hover { background: white; }
            `}</style>
        </div>
    );
}

"use client";

import { useEffect, useState } from "react";
import { db } from "@/lib/firebase";
import { collection, getDocs, query, orderBy, where, doc, updateDoc } from "firebase/firestore";
import Link from "next/link";
import { Copy, Check, Clock, AlertCircle } from "lucide-react";

export default function RequirementsDashboard() {
    const [requirements, setRequirements] = useState([]);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        const fetchRequirements = async () => {
            try {
                // Fetch all requirements
                const q = query(collection(db, "requirements"), orderBy("createdAt", "desc"));
                const querySnapshot = await getDocs(q);
                const reqs = querySnapshot.docs.map(doc => ({
                    id: doc.id,
                    ...doc.data()
                }));
                setRequirements(reqs);
            } catch (error) {
                console.error("Error fetching requirements:", error);
            } finally {
                setLoading(false);
            }
        };

        fetchRequirements();
    }, []);

    const StatusBadge = ({ status }) => {
        const colors = {
            'NEW': 'bg-blue-500/10 text-blue-500 border-blue-500/20',
            'IN_REVIEW': 'bg-yellow-500/10 text-yellow-500 border-yellow-500/20',
            'ASSIGNED': 'bg-purple-500/10 text-purple-500 border-purple-500/20',
            'COMPLETED': 'bg-green-500/10 text-green-500 border-green-500/20',
            'REJECTED': 'bg-red-500/10 text-red-500 border-red-500/20',
        };
        const colorClass = colors[status] || 'bg-gray-500/10 text-gray-500 border-gray-500/20';

        return (
            <span className={`px-2 py-0.5 rounded text-[10px] font-mono border ${colorClass}`}>
                {status}
            </span>
        );
    };

    return (
        <div className="p-8">
            <h1 className="text-3xl font-bold font-sans mb-8">REQUIREMENT_LOGS</h1>

            <div className="grid gap-6">
                {loading ? (
                    <div className="text-gray-500 font-mono animate-pulse">Scanning database...</div>
                ) : requirements.length === 0 ? (
                    <div className="text-gray-500 font-mono">No requirements found.</div>
                ) : (
                    requirements.map((req) => (
                        <div key={req.id} className="bg-black/40 border border-white/10 p-6 rounded-lg hover:border-white/20 transition-colors">
                            <div className="flex justify-between items-start mb-4">
                                <div>
                                    <div className="flex items-center gap-3 mb-2">
                                        <h3 className="text-xl font-bold font-sans">{req.name}</h3>
                                        <StatusBadge status={req.status} />
                                    </div>
                                    <p className="text-sm font-mono text-gray-400">{req.email} ΓÇó {req.type}</p>
                                </div>
                                <Link
                                    href={`/admin/requirements/view?id=${req.id}`}
                                    className="px-4 py-2 bg-white text-black font-bold font-mono text-xs rounded hover:bg-gray-200 transition-colors"
                                >
                                    MANAGE_OPEARTION
                                </Link>
                            </div>

                            <div className="bg-white/5 p-4 rounded text-sm text-gray-300 font-mono mb-4 whitespace-pre-wrap">
                                {req.description.length > 200 ? req.description.substring(0, 200) + "..." : req.description}
                            </div>

                            <div className="flex gap-4 text-xs font-mono text-gray-500">
                                <span>DEADLINE: {req.deadline || "N/A"}</span>
                                <span>BUDGET: {req.budget || "N/A"}</span>
                                <span>TASKS: {req.internalTasks?.length || 0}</span>
                            </div>
                        </div>
                    ))
                )}
            </div>
        </div>
    );
}

"use client";

