                                    </form>
                                </div>
                            )}
                        </motion.div>
                    ) : (
                        <motion.div
                            key="report"
                            initial={{ opacity: 0, y: 50 }}
                            animate={{ opacity: 1, y: 0 }}
                            className="max-w-4xl mx-auto"
                        >
                            <button
                                onClick={() => setReport(null)}
                                className="mb-6 text-xs text-gray-500 hover:text-white flex items-center gap-2"
