        teamName: "",
        members: [
            { name: "", email: "", phone: "", type: "STUDENT", details: { college: "", course: "", year: "" } }
        ]
    });

    useEffect(() => {
        if (user) {
            fetchRegistration();
        }
        fetchEventStatus();
    }, [user]);

    const fetchEventStatus = async () => {
        try {
            const q = query(collection(db, "hackathons"), where("isSpecialEvent", "==", true), limit(1));
            const querySnapshot = await getDocs(q);
            if (!querySnapshot.empty) {
                setChallengeEvent(querySnapshot.docs[0].data());
            }
        } catch (error) {
            console.error("Error fetching event status:", error);
        }
    };

    const fetchRegistration = async () => {
        try {
            const q = query(collection(db, "challenge_registrations"), where("registeredBy", "==", user.uid));
            const querySnapshot = await getDocs(q);
            if (!querySnapshot.empty) {
                const docData = querySnapshot.docs[0].data();
                setExistingRegistration({ id: querySnapshot.docs[0].id, ...docData });
                setFormData({
                    teamName: docData.teamName,
                    members: docData.members
                });
            }
        } catch (error) {
            console.error("Error fetching registration:", error);
        }
    };

    const handleAddMember = () => {
        if (formData.members.length < 4) {
            setFormData({
                ...formData,
                members: [...formData.members, { name: "", email: "", phone: "", type: "STUDENT", details: { college: "", course: "", year: "" } }]
            });
        }
    };

    const handleRemoveMember = (index) => {
        if (formData.members.length > 2) { // Min 2 members
            const updated = [...formData.members];
            updated.splice(index, 1);
            setFormData({ ...formData, members: updated });
        }
    };

    const updateMember = (index, field, value) => {
        const updated = [...formData.members];
        updated[index] = { ...updated[index], [field]: value };
        setFormData({ ...formData, members: updated });
    };

    const updateMemberDetail = (index, field, value) => {
        const updated = [...formData.members];
        updated[index].details = { ...updated[index].details, [field]: value };
        setFormData({ ...formData, members: updated });
    };

    const notifyBackend = async () => {
        try {
            const leadMember = formData.members[0];
            const apiUrl = process.env.NEXT_PUBLIC_API_URL !== undefined ? process.env.NEXT_PUBLIC_API_URL : 'http://localhost:8080';
            await fetch(`${apiUrl}/api/notify/challenge-connected`, {
                method: "POST",
                headers: {
                    "Content-Type": "application/json",
                },
                body: JSON.stringify({
                    email: leadMember.email,
                    teamName: formData.teamName,
                    leadName: leadMember.name
                }),
            });
        } catch (error) {
            console.error("Failed to signal backend:", error);
            // Non-blocking error, we don't stop the user flow
        }
    };

    const handleSubmitRegistration = async () => {
        setIsSubmitting(true);
        try {
            if (existingRegistration) {
                // Update existing
                await setDoc(doc(db, "challenge_registrations", existingRegistration.id), {
                    ...formData,
                    registeredBy: user.uid,
                    updatedAt: new Date().toISOString(),
                    status: existingRegistration.status || "PENDING"
                }, { merge: true });
                setDialog({ show: true, message: "SQUAD_DETAILS_UPDATED", type: "success" });
                setIsEditing(false);
                fetchRegistration(); // Refresh
                // Optional: Send email on update? Probably not necessary for now.
            } else {
                // Create new
                await addDoc(collection(db, "challenge_registrations"), {
                    ...formData,
                    registeredBy: user.uid,
                    registeredAt: new Date().toISOString(),
                    status: "PENDING"
                });

                // Trigger Email Notification
                await notifyBackend();

                setDialog({ show: true, message: "SQUAD_REGISTERED: Prepare for deployment.", type: "success" });
                setRegistrationStep(3); // Success Screen
                fetchRegistration();
            }
        } catch (error) {
            setDialog({ show: true, message: "REGISTRATION_FAILED: " + error.message, type: "error" });
        } finally {
            setIsSubmitting(false);
        }
    };

    return (
        <div className="min-h-screen bg-[#050505] text-white p-6 pt-28 relative overflow-hidden">
            <div className="fixed inset-0 grid-bg opacity-10 pointer-events-none"></div>

            {/* Dialog Modal */}
            {dialog.show && (
                <div className="fixed inset-0 z-[200] flex items-center justify-center p-4 bg-black/80 backdrop-blur-sm animate-in fade-in duration-200">
                    <div className="bg-[#0a0a0a] border border-white/10 p-8 max-w-md w-full relative shadow-2xl flex flex-col items-center text-center">
                        <div className={`mb-4 p-4 rounded-full ${dialog.type === 'error' ? 'bg-red-500/10 text-red-500' : 'bg-neon-green/10 text-neon-green'}`}>
                            {dialog.type === 'error' ? <Zap size={32} /> : <Award size={32} />}
                        </div>
                        <h3 className="text-xl font-bold font-sans text-white mb-2">{dialog.type === 'error' ? 'SYSTEM_ERROR' : 'OPERATION_COMPLETE'}</h3>
                        <p className="font-mono text-sm text-gray-400 mb-6">{dialog.message}</p>
                        <button
                            onClick={() => setDialog({ ...dialog, show: false })}
                            className="w-full bg-white/10 hover:bg-white/20 text-white font-mono py-2 text-sm uppercase tracking-wider transition-colors"
                        >
                            CLOSE_DIALOG
                        </button>
                    </div>
                </div>
            )}

            <div className="max-w-6xl mx-auto relative z-10">
                <Link href="/" className="inline-flex items-center text-gray-400 hover:text-purple-400 transition-colors mb-8">
                    <ArrowLeft size={16} className="mr-2" />
                    // RETURN_HQ
                </Link>

                {/* Hero Header */}
                <div className="mb-12 border-b border-white/10 pb-8">
                    <div className="flex items-center gap-3 mb-4">
                        <span className={`px-3 py-1 text-[10px] font-mono rounded border animate-pulse ${challengeEvent?.status === 'UPCOMING' ? 'bg-yellow-500/10 text-yellow-500 border-yellow-500/20' : 'bg-red-500/10 text-red-500 border-red-500/20'}`}>
                            {challengeEvent?.status === 'UPCOMING' ? '/// COMING_SOON' : '/// LIVE_EVENT'}
                        </span>
                        <span className="text-gray-500 font-mono text-xs">GLOBAL_BROADCAST_ID: #DVC-2026</span>
                    </div>
                    <h1 className="text-5xl md:text-7xl font-bold font-sans mb-4 text-transparent bg-clip-text bg-gradient-to-r from-white via-purple-200 to-gray-500">
                        DEVERT <span className="text-purple-500">INNOVATION</span> CHALLENGE
                    </h1>
                    <p className="text-gray-400 font-mono text-sm md:text-base max-w-2xl">
                        A localized innovation operation. Identify failures. Architect solutions.
                        No cash handoutsΓÇöonly high-value assets: Exclusive Gear, Swag, and Direct Industry Access.
                    </p>
                </div>

                {/* Navigation Tabs */}
                <div className="flex gap-4 mb-8 border-b border-white/5">
                    {["overview", "timeline", "register"].map((tab) => (
                        <button
                            key={tab}
                            onClick={() => setActiveTab(tab)}
                            className={`pb-4 px-2 font-mono text-sm uppercase tracking-wider transition-all relative ${activeTab === tab ? "text-purple-400" : "text-gray-500 hover:text-gray-300"
                                }`}
                        >
                            {tab}
                            {activeTab === tab && (
                                <motion.div layoutId="tab-underline" className="absolute bottom-0 left-0 right-0 h-0.5 bg-purple-500" />
                            )}
                        </button>
                    ))}
                </div>

                <AnimatePresence mode="wait">
                    {activeTab === "overview" && (
                        <motion.div
                            key="overview"
                            initial={{ opacity: 0, y: 20 }}
                            animate={{ opacity: 1, y: 0 }}
                            exit={{ opacity: 0, y: -20 }}
                            className="grid md:grid-cols-2 gap-12"
                        >
                            <div className="space-y-8">
                                <div className="bg-white/5 border border-white/10 p-8 hover:border-purple-500/30 transition-colors group">
                                    <Trophy className="text-yellow-500 mb-4 group-hover:scale-110 transition-transform" size={32} />
                                    <h3 className="text-2xl font-bold font-sans mb-2">The Rewards</h3>
                                    <ul className="space-y-3 font-mono text-sm text-gray-400">
                                        <li className="flex items-center gap-2"><Gift size={14} className="text-purple-400" /> Exclusive DeVert Operative Swag Kits</li>
                                        <li className="flex items-center gap-2"><Briefcase size={14} className="text-purple-400" /> Gadgets</li>
                                        <li className="flex items-center gap-2"><Award size={14} className="text-purple-400" /> Verified Merit Certificates</li>
                                        <li className="flex items-center gap-2"><Target size={14} className="text-purple-400" /> Fast-Track Interviews with Partner NGOs/Tech Corps</li>
                                    </ul>
                                </div>

                                <div className="bg-white/5 border border-white/10 p-8">
                                    <Users className="text-neon-cyan mb-4" size={32} />
                                    <h3 className="text-2xl font-bold font-sans mb-2">Squad Requirements</h3>
                                    <div className="grid grid-cols-2 gap-4 mt-4">
                                        <div className="p-4 bg-black/40 rounded border border-white/5 text-center">
                                            <div className="text-3xl font-bold text-white mb-1">2</div>
                                            <div className="text-[10px] font-mono text-gray-500">MIN_MEMBERS</div>
                                        </div>
                                        <div className="p-4 bg-black/40 rounded border border-white/5 text-center">
                                            <div className="text-3xl font-bold text-white mb-1">4</div>
                                            <div className="text-[10px] font-mono text-gray-500">MAX_MEMBERS</div>
                                        </div>
                                    </div>
                                    <p className="mt-4 text-xs font-mono text-gray-500">
                                        *Squads can be mixed (Students + Professionals).
                                    </p>
                                </div>
                            </div>

                            <div className="relative h-full min-h-[400px] bg-purple-900/10 border border-purple-500/20 p-8 flex flex-col justify-between">
                                <div className="absolute top-0 right-0 p-4 opacity-50">
                                    <Zap size={120} className="text-purple-500/20" />
                                </div>
                                <div>
                                    <h3 className="text-3xl font-bold font-sans mb-4">Mission Briefing</h3>
                                    <p className="text-gray-300 mb-6 leading-relaxed">
                                        Your objective is to identify a critical failure in current societal or business systems and architect a technological solution.
                                        This is not about flashy UI. It is about functionality, scalability, and genuine impact.
                                    </p>
                                    <div className="space-y-4">
                                        <div className="flex items-start gap-4 p-4 bg-black/40 border border-white/5 rounded">
                                            <span className="text-purple-500 font-bold font-mono">01</span>
                                            <p className="text-sm text-gray-400">Identify a Problem Statement (or choose from our bounty board).</p>
                                        </div>
                                        <div className="flex items-start gap-4 p-4 bg-black/40 border border-white/5 rounded">
                                            <span className="text-purple-500 font-bold font-mono">02</span>
                                            <p className="text-sm text-gray-400">Form a Squad (2-4 Members). Register before the deadline.</p>
                                        </div>
                                        <div className="flex items-start gap-4 p-4 bg-black/40 border border-white/5 rounded">
                                            <span className="text-purple-500 font-bold font-mono">03</span>
                                            <p className="text-sm text-gray-400">Submit Blueprint (PPT/PDF) proposing the solution architecture.</p>
                                        </div>
                                    </div>
                                </div>
                                <button
                                    onClick={() => {
                                        if (challengeEvent?.status !== 'UPCOMING') setActiveTab("register");
                                    }}
                                    disabled={challengeEvent?.status === 'UPCOMING'}
                                    className={`mt-8 w-full py-4 font-bold font-mono transition-colors ${challengeEvent?.status === 'UPCOMING' ? 'bg-gray-800 text-gray-500 cursor-not-allowed border border-gray-700' : 'bg-purple-600 hover:bg-purple-500 text-white'}`}
                                >
                                    {challengeEvent?.status === 'UPCOMING' ? 'REGISTRATION_LOCKED // COMING_SOON' : 'INITIATE_REGISTRATION'}
                                </button>
                            </div>
                        </motion.div>
                    )}

                    {activeTab === "timeline" && (
                        <motion.div
                            key="timeline"
                            initial={{ opacity: 0, x: 20 }}
                            animate={{ opacity: 1, x: 0 }}
                            exit={{ opacity: 0, x: -20 }}
                            className="max-w-4xl mx-auto"
                        >
                            <div className="space-y-8 relative before:absolute before:inset-0 before:ml-5 before:-translate-x-px md:before:mx-auto md:before:translate-x-0 before:h-full before:w-0.5 before:bg-gradient-to-b before:from-transparent before:via-purple-500 before:to-transparent">
                                {[
                                    { date: "Jan 12, 2026", title: "Registrations Open", desc: "Squad formation protocols active.", status: "LIVE" },
                                    { date: "TBA", title: "Registration Deadline", desc: "Last date to register your squad.", status: "UPCOMING" },
                                    { date: "TBA", title: "Idea Submission (PPT)", desc: "Submit your solution blueprint via the dashboard.", status: "LOCKED" },
                                    { date: "TBA", title: "Shortlisting", desc: "Top 20 teams moved to Deployment Phase.", status: "LOCKED" },
                                    { date: "TBA", title: "Evaluation & Screening", desc: "Detailed review of deployed solutions.", status: "LOCKED" },
                                    { date: "TBA", title: "Final Results", desc: "Winners declared. Swag packs dispatched.", status: "LOCKED" }
                                ].map((item, index) => (
                                    <div key={index} className="relative flex items-center justify-between md:justify-normal md:odd:flex-row-reverse group is-active">
                                        <div className="flex items-center justify-center w-10 h-10 rounded-full border border-purple-500 bg-[#0a0a0a] group-hover:bg-purple-500/20 shadow-[0_0_10px_rgba(168,85,247,0.3)] shrink-0 md:order-1 md:group-odd:-translate-x-1/2 md:group-even:translate-x-1/2 z-10 transition-colors">
                                            <Calendar size={16} className="text-purple-400" />
                                        </div>
                                        <div className="w-[calc(100%-4rem)] md:w-[calc(50%-2.5rem)] bg-white/5 border border-white/10 p-6 rounded hover:border-purple-500/50 transition-colors">
                                            <div className="flex items-center justify-between mb-2">
                                                <time className="font-mono text-xs text-purple-400 font-bold">{item.date}</time>
                                                <span className={`text-[10px] px-2 py-0.5 rounded border ${item.status === 'LIVE' ? 'border-red-500 text-red-500 animate-pulse' : 'border-gray-700 text-gray-500'}`}>
                                                    {item.status}
                                                </span>
                                            </div>
                                            <h3 className="text-lg font-bold font-sans text-white mb-1">{item.title}</h3>
                                            <p className="text-gray-400 text-sm">{item.desc}</p>
                                        </div>
                                    </div>
                                ))}
                            </div>
                        </motion.div>
                    )}

                    {activeTab === "register" && (
                        <motion.div
                            key="register"
                            initial={{ opacity: 0, scale: 0.95 }}
                            animate={{ opacity: 1, scale: 1 }}
                            exit={{ opacity: 0, scale: 0.95 }}
                            className="max-w-3xl mx-auto bg-[#0a0a0a] border border-white/10 p-8 relative shadow-2xl"
                        >
                            {!user ? (
                                <div className="text-center py-20">
                                    <Shield size={48} className="mx-auto text-red-500 mb-4" />
                                    <h3 className="text-2xl font-bold font-sans mb-2">ACCESS_DENIED</h3>
                                    <p className="text-gray-400 mb-6 font-mono">Authentication required to access registration protocols.</p>
                                    <Link href="/login" className="px-8 py-3 bg-white text-black font-bold font-mono text-sm hover:bg-gray-200">
                                        LOGIN_TO_PROCEED
                                    </Link>
                                </div>
                            ) : existingRegistration && !isEditing ? (
                                <div className="text-center py-10">
                                    <div className="w-20 h-20 bg-neon-green/10 rounded-full flex items-center justify-center mx-auto mb-6">
                                        <CheckCircle size={40} className="text-neon-green" />
                                    </div>
                                    <h3 className="text-2xl font-bold font-sans mb-2">SQUAD_REGISTERED</h3>
                                    <p className="text-gray-400 mb-6 font-mono">You are already deployed for this mission.</p>

                                    <div className="bg-white/5 border border-white/10 p-6 rounded text-left mb-6 max-w-lg mx-auto">
                                        <div className="flex justify-between items-center mb-4">
                                            <span className="text-gray-500 font-mono text-xs">CODENAME</span>
                                            <span className="text-white font-bold">{existingRegistration.teamName}</span>
                                        </div>
                                        <div className="space-y-2">
                                            <span className="text-gray-500 font-mono text-xs block mb-2">OPERATIVES</span>
                                            {existingRegistration.members.map((m, i) => (
                                                <div key={i} className="flex justify-between items-center text-sm">
                                                    <span className="text-gray-300">{m.name}</span>
                                                    <span className="text-xs px-2 py-0.5 bg-purple-500/20 text-purple-400 rounded">{m.type}</span>
                                                </div>
                                            ))}
                                        </div>
                                    </div>

                                    <button
                                        onClick={() => { setIsEditing(true); setRegistrationStep(1); }}
                                        className="text-purple-400 hover:text-white font-mono text-sm underline"
                                    >
                                        [EDIT_SQUAD_DETAILS]
                                    </button>
                                </div>
                            ) : registrationStep === 3 ? (
                                <div className="text-center py-20">
                                    <div className="w-20 h-20 bg-neon-green/10 rounded-full flex items-center justify-center mx-auto mb-6">
                                        <CheckCircle size={40} className="text-neon-green" />
                                    </div>
                                    <h3 className="text-2xl font-bold font-sans mb-2">REGISTRATION_CONFIRMED</h3>
                                    <p className="text-gray-400 mb-6 font-mono max-w-md mx-auto">
                                        Your squad has been entered into the database. Check your email for the mission dossier.
                                    </p>
                                    <button onClick={() => { setRegistrationStep(1); setActiveTab("overview"); fetchRegistration(); }} className="text-purple-400 hover:text-white font-mono text-sm underline">
                                        RETURN_TO_BASE
                                    </button>
                                </div>
                            ) : (
                                <div>
                                    <h3 className="text-2xl font-bold font-sans mb-6 flex items-center justify-between">
                                        {isEditing ? "Update Squad Details" : "Squad Registration"}
                                        <span className="text-xs font-mono font-normal text-gray-500">STEP {registrationStep}/2</span>
                                    </h3>

                                    {registrationStep === 1 && (
                                        <div className="space-y-6">
                                            <div>
                                                <label className="block text-gray-400 font-mono text-xs mb-1">SQUAD_CODENAME (Team Name)</label>
                                                <input
                                                    type="text"
                                                    value={formData.teamName}
                                                    onChange={e => setFormData({ ...formData, teamName: e.target.value })}
                                                    className="w-full bg-white/5 border border-white/10 p-3 text-white focus:border-purple-500 outline-none"
                                                    placeholder="e.g. The Null Pointers"
                                                />
                                            </div>

                                            <div className="flex justify-between">
                                                {isEditing ? (
                                                    <button
                                                        onClick={() => setIsEditing(false)}
                                                        className="text-gray-500 hover:text-white font-mono text-xs"
                                                    >
                                                        CANCEL_EDIT
                                                    </button>
                                                ) : <div></div>}
                                                <button
                                                    onClick={() => setRegistrationStep(2)}
                                                    disabled={!formData.teamName}
                                                    className="px-6 py-3 bg-white/10 hover:bg-white/20 text-white font-mono text-sm disabled:opacity-50"
                                                >
                                                    NEXT_STEP: MEMBERS
                                                </button>
                                            </div>
                                        </div>
                                    )}

                                    {registrationStep === 2 && (
                                        <div className="space-y-8">
                                            {formData.members.map((member, index) => (
                                                <div key={index} className="p-6 bg-white/5 border border-white/10 relative group">
                                                    <div className="absolute top-0 left-0 bg-purple-500 text-black text-[10px] font-bold px-2 py-0.5 font-mono">
                                                        OPERATIVE_0{index + 1}
                                                    </div>
                                                    {index > 1 && (
                                                        <button
                                                            onClick={() => handleRemoveMember(index)}
                                                            className="absolute top-2 right-2 text-gray-500 hover:text-red-500"
                                                        >
                                                            <X size={16} />
                                                        </button>
                                                    )}

                                                    <div className="grid md:grid-cols-2 gap-4 mt-4">
                                                        <input
                                                            type="text"
                                                            placeholder="Full Name"
                                                            value={member.name}
                                                            onChange={e => updateMember(index, "name", e.target.value)}
                                                            className="w-full bg-black/20 border border-white/10 p-2 text-sm text-white focus:border-purple-500 outline-none"
                                                        />
                                                        <input
                                                            type="email"
                                                            placeholder="Email Address"
                                                            value={member.email}
                                                            onChange={e => updateMember(index, "email", e.target.value)}
                                                            className="w-full bg-black/20 border border-white/10 p-2 text-sm text-white focus:border-purple-500 outline-none"
                                                        />
                                                        <input
                                                            type="tel"
                                                            placeholder="Phone Number"
                                                            value={member.phone}
                                                            onChange={e => updateMember(index, "phone", e.target.value)}
                                                            className="w-full bg-black/20 border border-white/10 p-2 text-sm text-white focus:border-purple-500 outline-none"
                                                        />
                                                        <select
                                                            value={member.type}
                                                            onChange={e => updateMember(index, "type", e.target.value)}
                                                            className="w-full bg-black/20 border border-white/10 p-2 text-sm text-white focus:border-purple-500 outline-none"
                                                        >
                                                            <option value="STUDENT">Student</option>
                                                            <option value="PROFESSIONAL">Working Professional</option>
                                                        </select>
                                                    </div>

                                                    <div className="mt-4 pt-4 border-t border-white/5 grid md:grid-cols-3 gap-4">
                                                        {member.type === "STUDENT" ? (
                                                            <>
                                                                <input
                                                                    type="text"
                                                                    placeholder="College Name"
                                                                    value={member.details.college}
                                                                    onChange={e => updateMemberDetail(index, "college", e.target.value)}
                                                                    className="w-full bg-black/20 border border-white/10 p-2 text-xs text-gray-300 focus:border-purple-500 outline-none"
                                                                />
                                                                <input
                                                                    type="text"
                                                                    placeholder="Course/Degree"
                                                                    value={member.details.course}
                                                                    onChange={e => updateMemberDetail(index, "course", e.target.value)}
                                                                    className="w-full bg-black/20 border border-white/10 p-2 text-xs text-gray-300 focus:border-purple-500 outline-none"
                                                                />
                                                                <input
                                                                    type="text"
                                                                    placeholder="current Year"
                                                                    value={member.details.year}
                                                                    onChange={e => updateMemberDetail(index, "year", e.target.value)}
                                                                    className="w-full bg-black/20 border border-white/10 p-2 text-xs text-gray-300 focus:border-purple-500 outline-none"
                                                                />
                                                            </>
                                                        ) : (
                                                            <>
                                                                <input
                                                                    type="text"
                                                                    placeholder="Company Name"
                                                                    value={member.details.company}
                                                                    onChange={e => updateMemberDetail(index, "company", e.target.value)}
                                                                    className="w-full bg-black/20 border border-white/10 p-2 text-xs text-gray-300 focus:border-purple-500 outline-none"
                                                                />
                                                                <input
                                                                    type="text"
                                                                    placeholder="Role/Designation"
                                                                    value={member.details.role}
                                                                    onChange={e => updateMemberDetail(index, "role", e.target.value)}
                                                                    className="w-full bg-black/20 border border-white/10 p-2 text-xs text-gray-300 focus:border-purple-500 outline-none"
                                                                />
                                                                <input
                                                                    type="text"
                                                                    placeholder="Years of Exp"
                                                                    value={member.details.experience}
                                                                    onChange={e => updateMemberDetail(index, "experience", e.target.value)}
                                                                    className="w-full bg-black/20 border border-white/10 p-2 text-xs text-gray-300 focus:border-purple-500 outline-none"
                                                                />
                                                            </>
                                                        )}
                                                    </div>
                                                </div>
                                            ))}

                                            {formData.members.length < 4 && (
                                                <button
                                                    onClick={handleAddMember}
                                                    className="w-full py-3 border border-dashed border-white/20 text-gray-500 font-mono text-xs hover:border-purple-500 hover:text-purple-400 transition-colors flex items-center justify-center gap-2"
                                                >
                                                    <Plus size={16} /> ADD_OPERATIVE
                                                </button>
                                            )}

                                            <div className="flex justify-between pt-6 border-t border-white/10">
                                                <button
                                                    onClick={() => setRegistrationStep(1)}
                                                    className="text-gray-500 hover:text-white font-mono text-xs"
                                                >
                                                    BACK
                                                </button>
                                                <button
                                                    onClick={handleSubmitRegistration}
                                                    disabled={isSubmitting}
                                                    className="px-8 py-3 bg-purple-600 hover:bg-purple-500 text-white font-bold font-mono text-sm shadow-[0_0_20px_rgba(168,85,247,0.3)] disabled:opacity-50"
                                                >
                                                    {isSubmitting ? "ENCRYPTING_DATA..." : isEditing ? "UPDATE_RECORDS" : "CONFIRM_REGISTRATION"}
                                                </button>
                                            </div>
                                        </div>
                                    )}
                                </div>
                            )}
                        </motion.div>
                    )}
                </AnimatePresence>
            </div>
        </div>
    );
}

// Icons needed that might not be imported yet

"use client";

import { motion, AnimatePresence } from "framer-motion";
import Link from "next/link";
import { ArrowLeft, Rocket, Zap, Plus, X, Shield, CheckCircle, Lightbulb, ThumbsUp, Users, Target, Edit3, Save, StopCircle, Eye, EyeOff, AlertTriangle } from "lucide-react";
import { useEffect, useState } from "react";
import { collection, getDocs, addDoc, updateDoc, doc, arrayUnion, arrayRemove, writeBatch, getDoc, setDoc } from "firebase/firestore";
import { db } from "@/lib/firebase";
import { useAuth } from "@/context/AuthContext";
import { useRouter } from "next/navigation";
import FeatureGuard from "@/components/feature-guard";

export default function IncubatorPage() {
    return (
        <FeatureGuard feature="incubator">
            <IncubatorPageContent />
        </FeatureGuard>
    );
}

function IncubatorPageContent() {
    const { user } = useAuth();
    const router = useRouter();
    const isAdmin = user?.email?.includes("admin");

    const [ideas, setIdeas] = useState([]);
    const [editedIdeas, setEditedIdeas] = useState([]);
    const [loading, setLoading] = useState(true);
    const [filter, setFilter] = useState("ALL"); // ALL, TRENDING, NEW, MY_IDEAS
    const [dialog, setDialog] = useState({ show: false, message: "", type: "info" });

    // Module Status State
    const [isModuleEnabled, setIsModuleEnabled] = useState(true);

    // Edit Mode State
    const [isEditing, setIsEditing] = useState(false);
    const [saving, setSaving] = useState(false);

    // Submit Idea Modal
    const [isIdaModalOpen, setIsIdeaModalOpen] = useState(false);
    const [ideaForm, setIdeaForm] = useState({
        title: "",
        problem: ""
    });
    const [submitting, setSubmitting] = useState(false);

    useEffect(() => {
        fetchIdeas();
        fetchModuleStatus();
    }, []);

    async function fetchModuleStatus() {
        try {
            const docRef = doc(db, "system", "feature_flags");
            const docSnap = await getDoc(docRef);
            if (docSnap.exists()) {
                const data = docSnap.data();
                if (data.incubator === false) setIsModuleEnabled(false);
            }
        } catch (error) {
            console.error("Error fetching module status:", error);
        }
    }

    const toggleModuleStatus = async () => {
        const newState = !isModuleEnabled;
        setIsModuleEnabled(newState);
        try {
            await setDoc(doc(db, "system", "feature_flags"), {
                incubator: newState
            }, { merge: true });
        } catch (error) {
            console.error("Error toggling module:", error);
            setIsModuleEnabled(!newState); // Revert
            setDialog({ show: true, message: "FAILED_TO_TOGGLE_MODULE", type: "error" });
        }
    }

    const fetchIdeas = async () => {
        try {
            const querySnapshot = await getDocs(collection(db, "incubator_ideas"));
            const data = querySnapshot.docs.map(doc => ({
                id: doc.id,
                ...doc.data()
            }));

            data.sort((a, b) => (b.votes?.length || 0) - (a.votes?.length || 0));

            if (data.length === 0) {
                setIdeas(MOCK_IDEAS);
                setEditedIdeas(JSON.parse(JSON.stringify(MOCK_IDEAS)));
            } else {
                setIdeas(data);
                setEditedIdeas(JSON.parse(JSON.stringify(data)));
            }
        } catch (error) {
            console.error("Error fetching ideas:", error);
            if (ideas.length === 0) {
                setIdeas(MOCK_IDEAS);
                setEditedIdeas(JSON.parse(JSON.stringify(MOCK_IDEAS)));
            }
        } finally {
            setLoading(false);
        }
    };

    const handleEditChange = (id, field, value) => {
        setEditedIdeas(prev => prev.map(item => {
            if (item.id === id) {
                return { ...item, [field]: value };
            }
            return item;
        }));
    };

    const saveChanges = async () => {
        setSaving(true);
        try {
            const batch = writeBatch(db);

            editedIdeas.forEach(idea => {
                // Skip mocks if they have numeric IDs and we are using real DB (usually mocks handle separately but let's try)
                // In this app structure, ideally we only edit real data.
                if (idea.id && idea.id.length > 5) { // Simple check for non-mock ID if mocks are "1", "2"
                    const docRef = doc(db, "incubator_ideas", idea.id);
                    const { id, ...data } = idea;
                    batch.update(docRef, data);
                }
            });

            await batch.commit();
            setIdeas(JSON.parse(JSON.stringify(editedIdeas)));
            setDialog({ show: true, message: "ALL_SYSTEMS_UPDATED", type: "success" });
            setIsEditing(false);
        } catch (err) {
            console.error("Error saving changes:", err);
            // If it fails (e.g. mock data), just show success for UI demo if needed, but better to error.
            setDialog({ show: true, message: "SAVE_FAILED (Are these mock items?): " + err.message, type: "error" });
        } finally {
            setSaving(false);
        }
    };

    const handleVote = async (ideaId, currentVotes) => {
        if (!user) {
            setDialog({ show: true, message: "AUTH_REQUIRED: LOG_IN_TO_VOTE", type: "error" });
            return;
        }

        const hasVoted = currentVotes?.includes(user.email);
        const ref = doc(db, "incubator_ideas", ideaId);

        try {
            if (hasVoted) {
                await updateDoc(ref, { votes: arrayRemove(user.email) });
            } else {
                await updateDoc(ref, { votes: arrayUnion(user.email) });
            }
            // Optimistic update
            setIdeas(prev => prev.map(idea => {
                if (idea.id === ideaId) {
                    const newVotes = hasVoted
                        ? idea.votes.filter(v => v !== user.email)
                        : [...(idea.votes || []), user.email];
                    return { ...idea, votes: newVotes };
                }
                return idea;
            }));
            // Also update edited state so if we toggle edit mode it has latest votes
            setEditedIdeas(prev => prev.map(idea => {
                if (idea.id === ideaId) {
                    const newVotes = hasVoted
                        ? idea.votes.filter(v => v !== user.email)
                        : [...(idea.votes || []), user.email];
                    return { ...idea, votes: newVotes };
                }
                return idea;
            }));
        } catch (err) {
            console.error(err);
        }
    };

    const handleSubmitIdea = async (e) => {
        e.preventDefault();
        setSubmitting(true);
        try {
            await addDoc(collection(db, "incubator_ideas"), {
                ...ideaForm,
                // Default values for fields we removed
                solution: "",
                tags: [],
                votes: [],
                author: user.email,
                authorName: user.displayName || user.email.split('@')[0],
                status: "CONCEPT", // CONCEPT, IN_DEV, LAUNCHED
                createdAt: new Date().toISOString()
            });
            setDialog({ show: true, message: "BLUEPRINT_UPLOADED: AWAITING_COMMUNITY_FEEDBACK", type: "success" });
            setIsIdeaModalOpen(false);
            setIdeaForm({ title: "", problem: "" });
            fetchIdeas();
        } catch (err) {
            console.error(err);
            setDialog({ show: true, message: "UPLOAD_FAILED: " + err.message, type: "error" });
        } finally {
            setSubmitting(false);
        }
    };

    // Filter Logic
    const displayData = isEditing ? editedIdeas : ideas;

    const filteredIdeas = displayData.filter(idea => {
        if (filter === "ALL") return true;
        if (filter === "TRENDING") return (idea.votes?.length || 0) > 5;
        if (filter === "MY_IDEAS") return user && idea.author === user.email;
        return true;
    });

    return (
        <div className="min-h-screen bg-background text-foreground p-6 pt-28 pb-32">
            <div className="fixed inset-0 grid-bg opacity-10 pointer-events-none"></div>

            {/* Dialog Modal */}
            {dialog.show && (
                <div className="fixed inset-0 z-[200] flex items-center justify-center p-4 bg-black/80 backdrop-blur-sm animate-in fade-in duration-200">
                    <div className="bg-card-bg border border-border p-8 max-w-md w-full relative shadow-2xl flex flex-col items-center text-center">
                        <div className={`mb-4 p-4 rounded-full ${dialog.type === 'error' ? 'bg-red-500/10 text-red-500' : 'bg-neon-green/10 text-neon-green'}`}>
                            {dialog.type === 'error' ? <Shield size={32} /> : <CheckCircle size={32} />}
                        </div>
                        <h3 className="text-xl font-bold font-sans text-foreground mb-2">{dialog.type === 'error' ? 'SYSTEM_ERROR' : 'OPERATION_COMPLETE'}</h3>
                        <p className="font-mono text-sm text-muted-foreground mb-6">{dialog.message}</p>
                        <button
                            onClick={() => setDialog({ ...dialog, show: false })}
                            className="w-full bg-border hover:bg-neon-cyan/20 text-foreground font-mono py-2 text-sm uppercase tracking-wider transition-colors"
                        >
                            CLOSE_DIALOG
                        </button>
                    </div>
                </div>
            )}

            <div className="max-w-7xl mx-auto relative z-10">

                {/* Admin Disabled Warning */}
                {!isModuleEnabled && isAdmin && (
                    <div className="mb-8 p-4 bg-red-500/10 border border-red-500 flex items-center justify-between animate-pulse">
                        <div className="flex items-center gap-4 text-red-500">
                            <AlertTriangle size={24} />
                            <div>
                                <h3 className="font-bold font-mono">MODULE DISABLED (PUBLIC)</h3>
                                <p className="text-xs">Regular users see 'Under Construction'. You have bypass access.</p>
                            </div>
                        </div>
                        <button
                            onClick={toggleModuleStatus}
                            className="px-4 py-2 bg-red-500 text-white font-mono text-xs font-bold hover:bg-neon-green hover:text-black transition-colors"
                        >
                            ENABLE NOW
                        </button>
                    </div>
                )}

                <div className="flex flex-col md:flex-row justify-between items-start md:items-center mb-12 gap-4">
                    <div>
                        <Link href="/" className="inline-flex items-center text-muted-foreground hover:text-purple-400 transition-colors mb-4">
                            <ArrowLeft size={16} className="mr-2" />
                            // RETURN HOME
                        </Link>
                        <h1 className="text-4xl md:text-6xl font-bold font-sans mb-2">
                            IDEAS <span className="text-purple-500">_</span>
                            {isEditing && <span className="text-red-500 text-sm align-middle ml-4 animate-pulse">[ADMIN_EDIT]</span>}
                        </h1>
                        <p className="text-muted-foreground font-mono text-sm max-w-2xl">
                            Share your moonshot ideas. Community votes. Builders build.
                        </p>
                    </div>

                    <div className="flex gap-4">
                        {isAdmin && (
                            <>
                                <button
                                    onClick={toggleModuleStatus}
                                    className={`border px-4 py-2 font-mono text-xs flex items-center gap-2 transition-colors ${isModuleEnabled
                                        ? "bg-neon-green/10 border-neon-green text-neon-green hover:bg-red-500 hover:border-red-500 hover:text-white"
                                        : "bg-red-500/10 border-red-500 text-red-500 hover:bg-neon-green hover:border-neon-green hover:text-black"
                                        }`}
                                    title={isModuleEnabled ? "Disable Public Access" : "Enable Public Access"}
                                >
                                    {isModuleEnabled ? <><Eye size={16} /> MODULE_ACTIVE</> : <><EyeOff size={16} /> MODULE_OFFLINE</>}
                                </button>
                                <button
                                    onClick={() => {
                                        if (isEditing) {
                                            setEditedIdeas(JSON.parse(JSON.stringify(ideas)));
                                            setIsEditing(false);
                                        } else {
                                            setIsEditing(true);
                                        }
                                    }}
                                    className={`border px-4 py-2 font-mono text-xs flex items-center gap-2 transition-colors ${isEditing
                                        ? "bg-red-500/10 border-red-500 text-red-500 hover:bg-red-500 hover:text-white"
                                        : "bg-purple-500/10 border-purple-500 text-purple-400 hover:bg-purple-500 hover:text-black"
                                        }`}
                                >
                                    {isEditing ? <><X size={16} /> CANCEL</> : <><Edit3 size={16} /> ADMIN_EDIT</>}
                                </button>
                            </>
                        )}
                        <button
                            onClick={() => {
                                if (!user) {
                                    router.push("/login");
                                    return;
                                }
                                setIsIdeaModalOpen(true);
                            }}
                            className="bg-purple-500/10 border border-purple-500 text-purple-400 px-6 py-3 font-mono text-xs font-bold flex items-center gap-2 hover:bg-purple-500 hover:text-black transition-all shadow-[0_0_20px_rgba(168,85,247,0.2)]"
                        >
                            <Lightbulb size={18} /> SUBMIT IDEA
                        </button>
                    </div>
                </div>

                {/* Dashboard Grid */}
                <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">

                    {/* LEFT COLUMN: Filters & Stats (3 cols) */}
                    <div className="lg:col-span-3 space-y-6">
                        <div className="bg-card-bg border border-border p-6">
                            <h3 className="text-sm font-bold font-sans text-muted-foreground mb-4 flex items-center gap-2">
                                <Target size={16} className="text-purple-500" /> FILTERS
                            </h3>
                            <div className="flex flex-col gap-2">
                                {["ALL", "TRENDING", "NEW", ...(user ? ["MY_IDEAS"] : [])].map(f => (
                                    <button
                                        key={f}
                                        onClick={() => setFilter(f)}
                                        className={`text-left px-4 py-2 font-mono text-xs transition-colors border-l-2 ${filter === f ? "border-purple-500 text-foreground bg-purple-500/10" : "border-transparent text-muted-foreground hover:text-gray-300"}`}
                                    >
                                        // {f}
                                    </button>
                                ))}
                            </div>
                        </div>

                        <div className="bg-card-bg border border-border p-6">
                            <h3 className="text-sm font-bold font-sans text-muted-foreground mb-4">INCUBATOR_STATS</h3>
                            <div className="space-y-4">
                                <div>
                                    <div className="text-2xl font-bold text-foreground mb-1">84</div>
                                    <div className="text-[10px] font-mono text-muted-foreground">TOTAL_SUBMISSIONS</div>
                                </div>
                                <div>
                                    <div className="text-2xl font-bold text-neon-green mb-1">12</div>
                                    <div className="text-[10px] font-mono text-muted-foreground">PROJECTS_LAUNCHED</div>
                                </div>
                                <div>
                                    <div className="text-2xl font-bold text-purple-500 mb-1">$42k</div>
                                    <div className="text-[10px] font-mono text-muted-foreground">VALUE_CREATED</div>
                                </div>
                            </div>
                        </div>
                    </div>

                    {/* RIGHT COLUMN: Idea Feed (9 cols) */}
                    <div className="lg:col-span-9">
                        {loading ? (
                            <div className="font-mono text-purple-500 animate-pulse">Loading ideas...</div>
                        ) : (
                            <div className="space-y-4">
                                {filteredIdeas.length === 0 ? (
                                    <div className="py-20 text-center border border-border border-dashed text-muted-foreground font-mono">
                                        No ideas yet. Be the first to submit one.
                                    </div>
                                ) : (
                                    filteredIdeas.map((idea, i) => (
                                        <motion.div
                                            key={idea.id}
                                            initial={{ opacity: 0, y: 20 }}
                                            animate={{ opacity: 1, y: 0 }}
                                            transition={{ delay: i * 0.05 }}
                                            className={`bg-card-bg border border-border p-6 transition-colors group relative overflow-hidden ${isEditing ? 'border-dashed border-purple-500/50' : 'hover:border-purple-500/50'}`}
                                        >
                                            <div className="flex justify-between items-start gap-4">
                                                <div className="flex-1">
                                                    {isEditing ? (
                                                        <div className="flex flex-col gap-3">
                                                            <div className="flex gap-2">
                                                                <input
                                                                    value={idea.title}
                                                                    onChange={(e) => handleEditChange(idea.id, "title", e.target.value)}
                                                                    className="flex-1 bg-background border border-border p-2 font-bold font-sans text-lg text-foreground"
                                                                    placeholder="Title"
                                                                />
                                                                <select
                                                                    value={idea.status || 'CONCEPT'}
                                                                    onChange={(e) => handleEditChange(idea.id, "status", e.target.value)}
                                                                    className="bg-background border border-border text-xs px-2 py-1 outline-none text-foreground"
                                                                >
                                                                    <option value="CONCEPT">CONCEPT</option>
                                                                    <option value="IN_DEV">IN_DEV</option>
                                                                    <option value="LAUNCHED">LAUNCHED</option>
                                                                </select>
                                                            </div>
                                                            <textarea
                                                                value={idea.problem}
                                                                onChange={(e) => handleEditChange(idea.id, "problem", e.target.value)}
                                                                className="bg-background border border-border p-2 font-mono text-xs text-muted-foreground w-full resize-none"
                                                                placeholder="Problem"
                                                            />
                                                            <textarea
                                                                value={idea.solution || ""}
                                                                onChange={(e) => handleEditChange(idea.id, "solution", e.target.value)}
                                                                className="bg-background border border-border p-2 font-mono text-xs text-muted-foreground w-full resize-none"
                                                                placeholder="Solution"
                                                            />
                                                        </div>
                                                    ) : (
                                                        <>
                                                            <div className="flex items-center gap-3 mb-2">
                                                                <span className={`px-2 py-0.5 text-[10px] font-mono rounded border ${idea.status === 'LAUNCHED' ? 'border-neon-green text-neon-green' :
                                                                    idea.status === 'IN_DEV' ? 'border-purple-500 text-purple-500' :
                                                                        'border-gray-500 text-gray-500'
                                                                    }`}>
                                                                    {idea.status || 'CONCEPT'}
                                                                </span>
                                                                <span className="text-xs font-mono text-muted-foreground">by {idea.authorName}</span>
                                                            </div>
                                                            <h3 className="text-xl md:text-2xl font-bold font-sans text-foreground mb-3 group-hover:text-purple-400 transition-colors">{idea.title}</h3>

                                                            <div className="grid md:grid-cols-2 gap-4 mb-4">
                                                                <div className="bg-background/20 p-3 rounded border border-border">
                                                                    <div className="text-[10px] font-mono text-red-400 mb-1">THE PROBLEM</div>
                                                                    <p className="text-sm text-muted-foreground">{idea.problem}</p>
                                                                </div>
                                                                <div className="bg-background/20 p-3 rounded border border-border relative">
                                                                    <div className="text-[10px] font-mono text-neon-green mb-1">THE SOLUTION</div>
                                                                    {idea.solution ? (
                                                                        <p className="text-sm text-muted-foreground">{idea.solution}</p>
                                                                    ) : (
                                                                        <div className="text-muted-foreground text-xs font-mono italic flex flex-col items-center justify-center py-4 border border-dashed border-border rounded">
                                                                            <span>Awaiting Solution</span>
                                                                            <button className="mt-2 text-neon-green hover:underline">
                                                                                [Propose Solution]
                                                                            </button>
                                                                        </div>
                                                                    )}
                                                                </div>
                                                            </div>

                                                            <div className="flex flex-wrap gap-2 mb-4">
                                                                {idea.tags && (Array.isArray(idea.tags) ? idea.tags : idea.tags.split(',')).map((tag, idx) => (
                                                                    <span key={idx} className="text-[10px] font-mono px-2 py-1 bg-border rounded text-muted-foreground">#{tag}</span>
                                                                ))}
                                                                {(!idea.tags || idea.tags.length === 0) && (
                                                                    <span className="text-[10px] font-mono px-2 py-1 bg-border rounded text-muted-foreground">NO_TAGS_ASSIGNED</span>
                                                                )}
                                                            </div>
                                                        </>
                                                    )}
                                                </div>

                                                <div className="flex flex-col items-center gap-2">
                                                    <button
                                                        onClick={() => handleVote(idea.id, idea.votes)}
                                                        className={`flex flex-col items-center justify-center w-16 h-16 rounded border transition-all ${idea.votes?.includes(user?.email)
                                                            ? "bg-purple-500 text-black border-purple-500 shadow-[0_0_15px_rgba(168,85,247,0.5)]"
                                                            : "bg-card-bg border-border text-muted-foreground hover:border-purple-400 hover:text-purple-400"
                                                            }`}
                                                    >
                                                        <ThumbsUp size={20} className={idea.votes?.includes(user?.email) ? "fill-current" : ""} />
                                                        <span className="text-xs font-bold font-mono mt-1">{idea.votes?.length || 0}</span>
                                                    </button>
                                                </div>
                                            </div>
                                        </motion.div>
                                    ))
                                )}
                            </div>
                        )}
                    </div>
                </div>
            </div>

            {/* Admin Save Bar */}
            <AnimatePresence>
                {isEditing && (
                    <motion.div
                        initial={{ y: 100 }}
                        animate={{ y: 0 }}
                        exit={{ y: 100 }}
                        className="fixed bottom-0 left-0 right-0 p-4 bg-background/80 backdrop-blur-md border-t border-purple-500 z-50 flex items-center justify-between"
                    >
                        <div className="text-purple-500 font-mono text-sm animate-pulse">
                            ADMIN_MODE_ACTIVE // UNSAVED_changes
                        </div>
                        <div className="flex gap-4">
                            <button
                                onClick={() => {
                                    setIsEditing(false);
                                    setEditedIdeas(JSON.parse(JSON.stringify(ideas))); // Revert
                                }}
                                className="px-6 py-2 border border-red-500 text-red-500 font-mono text-sm hover:bg-red-500/10"
                            >
                                DISCARD
                            </button>
                            <button
                                onClick={saveChanges}
                                disabled={saving}
                                className="px-6 py-2 bg-purple-500 text-black font-bold font-mono text-sm hover:opacity-80 disabled:opacity-50 flex items-center gap-2"
                            >
                                {saving ? <><StopCircle className="animate-spin" size={16} /> SAVING...</> : <><Save size={16} /> SAVE_CHANGES</>}
                            </button>
                        </div>
                    </motion.div>
                )}
            </AnimatePresence>

            {/* Submit Idea Modal */}
            <AnimatePresence>
                {isIdaModalOpen && (
                    <motion.div
                        initial={{ opacity: 0 }}
                        animate={{ opacity: 1 }}
                        exit={{ opacity: 0 }}
                        className="fixed inset-0 z-[90] flex items-start justify-center pt-28 px-4 pb-4 bg-black/80 backdrop-blur-sm overflow-y-auto"
                    >
                        <motion.div
                            initial={{ scale: 0.9, opacity: 0 }}
                            animate={{ scale: 1, opacity: 1 }}
                            exit={{ scale: 0.9, opacity: 0 }}
                            className="bg-card-bg border border-border w-full max-w-2xl p-6 md:p-8 relative shadow-2xl max-h-[90vh] overflow-y-auto scrollbar-hide"
                        >
                            <button
                                onClick={() => setIsIdeaModalOpen(false)}
                                className="absolute top-4 right-4 text-muted-foreground hover:text-foreground"
                            >
                                <X size={20} />
                            </button>

                            <h2 className="text-2xl font-bold font-sans mb-2 text-foreground">SUBMIT IDEA</h2>
                            <p className="text-muted-foreground font-mono text-xs mb-6">Describe your idea. The community will vote to build it.</p>

                            <form onSubmit={handleSubmitIdea} className="space-y-6">
                                <div>
                                    <label className="block text-muted-foreground font-mono text-xs mb-1">Project Title</label>
                                    <input
                                        type="text"
                                        required
                                        value={ideaForm.title}
                                        onChange={e => setIdeaForm({ ...ideaForm, title: e.target.value })}
                                        className="w-full bg-background border border-border p-3 text-foreground focus:border-purple-500 outline-none"
                                        placeholder="e.g. Project Lazarus"
                                    />
                                </div>

                                <div>
                                    <label className="block text-red-400 font-mono text-xs mb-1">The Problem</label>
                                    <textarea
                                        required
                                        value={ideaForm.problem}
                                        onChange={e => setIdeaForm({ ...ideaForm, problem: e.target.value })}
                                        className="w-full bg-background border border-border p-3 text-foreground focus:border-red-500 outline-none h-48 resize-none"
                                        placeholder="What is broken?"
                                    />
                                </div>

                                <button
                                    type="submit"
                                    disabled={submitting}
                                    className="w-full bg-purple-500 text-black font-bold font-mono py-4 mt-2 hover:opacity-90 disabled:opacity-50 flex items-center justify-center gap-2"
                                >
                                    {submitting ? "UPLOADING..." : <><Rocket size={18} /> SUBMIT IDEA</>}
                                </button>
                            </form>

                        </motion.div>
                    </motion.div>
                )}
            </AnimatePresence>
        </div>
    );
}
