                                    <div className="flex gap-4">
                                        {github && <Github size={18} className="text-gray-500 hover:text-foreground cursor-pointer" />}
                                        {linkedin && <Linkedin size={18} className="text-gray-500 hover:text-foreground cursor-pointer" />}
