"use client";

import { useEffect, useState } from "react";
import { useAuth } from "@/context/AuthContext";
import { useRouter, usePathname } from "next/navigation";
import { Loader2, ShieldAlert } from "lucide-react";

export function ForceLoginGuard({ children }) {
    const { user, loading } = useAuth();
    const router = useRouter();
    const pathname = usePathname();
    const [isChecking, setIsChecking] = useState(true);

    useEffect(() => {
        if (!loading) {
            // List of public paths
            const publicPaths = ["/login"];

            // Logic: If not logged in AND not on a public path
            if (!user && !publicPaths.includes(pathname)) {
                // Redirect to login
                console.log("Force Login: Redirecting to /login");
                router.replace("/login");
            } else {
                setIsChecking(false);
            }
        }
    }, [user, loading, pathname, router]);

    // If loading auth state, show a minimal loader
    if (loading) {
        return (
            <div className="h-screen w-screen bg-[#050505] flex flex-col items-center justify-center text-white">
                <Loader2 className="animate-spin text-neon-cyan mb-4" size={32} />
                <p className="font-mono text-xs text-gray-500 animate-pulse">VERIFYING_IDENTITY...</p>
            </div>
        );
    }

    // While performing the redirect check for unauthenticated users on protected routes
    // we want to render nothing or a spinner to prevent "flash of content"
    if (!user && pathname !== "/login") {
        return (
            <div className="h-screen w-screen bg-[#050505] flex flex-col items-center justify-center text-white">
                <ShieldAlert className="text-red-500 mb-4 animate-pulse" size={32} />
                <p className="font-mono text-xs text-red-500">ACCESS_RESTRICTED // REDIRECTING</p>
            </div>
        );
    }

    return <>{children}</>;
}

"use client";

import { useState, useEffect } from "react";
import { motion } from "framer-motion";
import Link from "next/link";

export function Hero({ hasShownIntro }) {
    const fullText = "> Initializing Devert.in...";
    const [text, setText] = useState(hasShownIntro ? fullText : "");

    useEffect(() => {
        if (hasShownIntro) return;

        let i = 0;
        const interval = setInterval(() => {
            setText(fullText.slice(0, i));
            i++;
            if (i > fullText.length) clearInterval(interval);
        }, 50);
        return () => clearInterval(interval);
    }, [hasShownIntro]);

    return (
        <section className="min-h-screen flex flex-col items-center justify-center relative overflow-hidden pt-20">
            <div className="absolute inset-0 grid-bg opacity-30 z-0 pointer-events-none"></div>

            <div className="z-10 text-center px-4 max-w-5xl mx-auto">
                <motion.div
                    initial={{ opacity: hasShownIntro ? 1 : 0, y: hasShownIntro ? 0 : 20 }}
                    animate={{ opacity: 1, y: 0 }}
                    className="font-mono text-neon-green text-sm mb-6 tracking-[0.2em] uppercase"
                >
          // SYSTEM_READY
                </motion.div>

                <h1 className="text-4xl md:text-6xl lg:text-7xl font-bold font-sans mb-8 h-auto min-h-[5rem] md:min-h-[8rem] leading-tight">
                    <span className="text-white">{text}</span>
                    <span className="animate-pulse text-neon-cyan">_</span>
                </h1>

                <motion.p
                    initial={{ opacity: hasShownIntro ? 1 : 0 }}
                    animate={{ opacity: 1 }}
                    transition={{ delay: hasShownIntro ? 0 : 2.5 }}
                    className="text-gray-400 text-lg md:text-2xl font-mono mb-12 max-w-2xl mx-auto"
                >
                    &quot;From Logic to Hosting. The 1% Dev Roadmap.&quot;
                </motion.p>

                <motion.div
                    initial={{ opacity: hasShownIntro ? 1 : 0, scale: hasShownIntro ? 1 : 0.9 }}
                    animate={{ opacity: 1, scale: 1 }}
                    transition={{ delay: hasShownIntro ? 0 : 3 }}
                >
                    <GlitchButton />
                </motion.div>
            </div>

            <motion.div
                initial={{ opacity: hasShownIntro ? 1 : 0 }}
                animate={{ opacity: 1 }}
                transition={{ delay: hasShownIntro ? 0 : 4 }}
                className="absolute bottom-10 left-1/2 -translate-x-1/2 text-gray-500 text-xs font-mono animate-bounce"
            >
                SCROLL_TO_INITIATE
            </motion.div>
        </section>
    );
}

function GlitchButton() {
    const [label, setLabel] = useState("[ JOIN_THE_SQUAD ]");

    return (
        <Link href="/login">
            <button
                className="group relative px-8 py-4 bg-transparent border border-neon-cyan text-neon-cyan font-mono font-bold uppercase tracking-wider overflow-hidden hover:bg-neon-cyan/5 transition-all shadow-[0_0_10px_rgba(0,255,255,0.2)] hover:shadow-[0_0_20px_rgba(0,255,255,0.6)] cursor-pointer"
                onMouseEnter={() => setLabel("J01N_SQU4D")}
                onMouseLeave={() => setLabel("[ JOIN_THE_SQUAD ]")}
            >
                <span className="relative z-10 glitch-text" data-text={label}>
                    {label}
                </span>
                <div className="absolute inset-0 bg-neon-cyan/10 translate-y-full group-hover:translate-y-0 transition-transform duration-300"></div>
            </button>
        </Link>
    );
}

"use client";

import { motion, AnimatePresence } from "framer-motion";
import { Trophy, Award, Zap, Edit3, Save, Eye, EyeOff, StopCircle, X, AlertTriangle, Construction } from "lucide-react";
import Link from "next/link";
import { useState, useEffect } from "react";
import { doc, getDoc, setDoc } from "firebase/firestore";
import { db } from "@/lib/firebase";
import { useAuth } from "@/context/AuthContext";

const ICON_MAP = {
    trophy: <Trophy className="text-neon-cyan" size={32} />,
    award: <Award className="text-purple-500" size={32} />,
    zap: <Zap className="text-neon-green" size={32} />,
};

const DEFAULT_CONFIG = [
    {
        id: "hackathons",
        title: "Agent Build Sprints",
        desc: "Time-limited events. Build real AI agents solving practical tasks.",
        iconType: "trophy",
        border: "hover:border-neon-cyan",
        shadow: "hover:shadow-neon-cyan/20",
        href: "/hackathons",
        enabled: true
    },
    {
        id: "certifications",
        title: "Agent Workflows",
        desc: "Experiment and deploy. Scripts, tools & prompt strategies.",
        iconType: "award",
        border: "hover:border-purple-500",
        shadow: "hover:shadow-purple-500/20",
        href: "/courses",
        enabled: true
    },
    {
        id: "hacks",
        title: "Live Implementations",
        desc: "Not concepts. Working systems. Learn from real agent experiments.",
        iconType: "zap",
        border: "hover:border-neon-green",
        shadow: "hover:shadow-neon-green/20",
        href: "/resources",
        enabled: true
    }
];

export function LootBox() {
    const { user } = useAuth();
    const isAdmin = user?.email?.includes("admin");
    const [items, setItems] = useState(DEFAULT_CONFIG);
    const [editedItems, setEditedItems] = useState(DEFAULT_CONFIG);
    const [isEditing, setIsEditing] = useState(false);
    const [loading, setLoading] = useState(true);
    const [saving, setSaving] = useState(false);

    useEffect(() => {
        const fetchConfig = async () => {
            try {
                const docRef = doc(db, "system", "lootbox");
                const docSnap = await getDoc(docRef);

                if (docSnap.exists()) {
                    setItems(docSnap.data().items);
                    setEditedItems(docSnap.data().items);
                } else {
                    // Initialize if not exists
                    setItems(DEFAULT_CONFIG);
                    setEditedItems(DEFAULT_CONFIG);
                }
            } catch (error) {
                console.error("Error fetching lootbox config:", error);
            } finally {
                setLoading(false);
            }
        };

        fetchConfig();
    }, []);

    const handleEditChange = (index, field, value) => {
        const newItems = [...editedItems];
        newItems[index] = { ...newItems[index], [field]: value };
        setEditedItems(newItems);
    };

    // Immediate toggle for admins
    const toggleItemStatus = async (index) => {
        const newItems = [...items]; // Operate on live items if not in edit mode, but better to use state
        newItems[index].enabled = !newItems[index].enabled;
        setItems(newItems);

        // Optimistic update to DB
        try {
            await setDoc(doc(db, "system", "lootbox"), {
                items: newItems,
                updatedAt: new Date().toISOString(),
                updatedBy: user.email
            }, { merge: true });
        } catch (err) {
            console.error("Failed to toggle status", err);
            // Revert on error
            newItems[index].enabled = !newItems[index].enabled;
            setItems(newItems);
        }
    };

    const handleEditToggleEnable = (index) => {
        const newItems = [...editedItems];
        newItems[index] = { ...newItems[index], enabled: !newItems[index].enabled };
        setEditedItems(newItems);
    };

    const saveChanges = async () => {
        setSaving(true);
        try {
            await setDoc(doc(db, "system", "lootbox"), {
                items: editedItems,
                updatedAt: new Date().toISOString(),
                updatedBy: user.email
            });
            setItems(JSON.parse(JSON.stringify(editedItems)));
            setIsEditing(false);
        } catch (error) {
            console.error("Error saving lootbox config:", error);
            alert("Failed to save changes.");
        } finally {
            setSaving(false);
        }
    };

    const displayItems = isEditing ? editedItems : items;

    return (
        <section className="py-32 px-4 relative z-10">
            <div className="max-w-6xl mx-auto">
                <div className="flex items-end justify-between mb-16">
                    <div>
                        <h2 className="text-3xl md:text-5xl font-bold font-sans mb-2 text-foreground flex items-center gap-4">
                            AGENT_TOOLKIT
                            {isAdmin && (
                                <button
                                    onClick={() => {
                                        if (isEditing) {
                                            setEditedItems(JSON.parse(JSON.stringify(items)));
                                            setIsEditing(false);
                                        } else {
                                            setIsEditing(true);
                                        }
                                    }}
                                    className={`text-xs px-3 py-1 border rounded font-mono flex items-center gap-2 transition-colors ${isEditing
                                        ? "border-red-500 text-red-500 hover:bg-red-500/10"
                                        : "border-neon-cyan text-neon-cyan hover:bg-neon-cyan/10"
                                        }`}
                                >
                                    {isEditing ? <><X size={12} /> CANCEL</> : <><Edit3 size={12} /> ADMIN_EDIT</>}
                                </button>
                            )}
                        </h2>
                        <p className="font-mono text-gray-400">Equip your agents for deployment.</p>
                    </div>
                    <div className="hidden md:block w-1/3 h-[1px] bg-gradient-to-l from-transparent to-gray-700"></div>
                </div>

                <div className="grid md:grid-cols-3 gap-8">
                    {displayItems.map((item, i) => {
                        // View Logic
                        const isLive = item.enabled;
                        const showUnderConstruction = !isLive && !isAdmin && !isEditing;

                        if (showUnderConstruction) {
                            return (
                                <div key={i} className="h-full p-8 bg-card-bg/50 border border-white/5 flex flex-col items-center justify-center text-center relative overflow-hidden grayscale opacity-75">
                                    <div className="absolute inset-0 stripes-bg opacity-10"></div>
                                    <Construction className="text-yellow-500 mb-4 animate-pulse" size={48} />
                                    <h3 className="text-xl font-bold font-sans text-gray-500 mb-2">UNDER CONSTRUCTION</h3>
                                    <p className="font-mono text-xs text-gray-600">This module is currently being upgraded. Check back later.</p>
                                    <div className="mt-4 px-3 py-1 bg-yellow-500/10 text-yellow-500 text-[10px] font-mono border border-yellow-500/20 rounded">
                                        STATUS: 503_MAINTENANCE
                                    </div>
                                </div>
                            )
                        }

                        return (
                            <div key={i} className="h-full relative group">
                                {isEditing ? (
                                    // Edit Mode Card
                                    <div className={`p-6 bg-black border ${item.enabled ? 'border-neon-cyan/50' : 'border-gray-800 opacity-75'} flex flex-col h-full gap-4`}>
                                        <div className="flex justify-between items-center mb-2">
                                            <div className="font-mono text-xs text-gray-500">ITEM_{i + 1}</div>
                                            <button
                                                onClick={() => handleEditToggleEnable(i)}
                                                className={`flex items-center gap-2 px-3 py-1 rounded text-xs font-bold font-mono ${item.enabled ? 'bg-neon-green/20 text-neon-green' : 'bg-red-500/20 text-red-500'}`}
                                            >
                                                {item.enabled ? <><Eye size={12} /> ENABLED</> : <><EyeOff size={12} /> DISABLED</>}
                                            </button>
                                        </div>

                                        <div>
                                            <label className="text-[10px] font-mono text-gray-500 block mb-1">TITLE</label>
                                            <input
                                                value={item.title}
                                                onChange={e => handleEditChange(i, 'title', e.target.value)}
                                                className="w-full bg-white/5 border border-white/10 p-2 text-white font-bold"
                                            />
                                        </div>

                                        <div>
                                            <label className="text-[10px] font-mono text-gray-500 block mb-1">DESCRIPTION</label>
                                            <textarea
                                                value={item.desc}
                                                onChange={e => handleEditChange(i, 'desc', e.target.value)}
                                                className="w-full bg-white/5 border border-white/10 p-2 text-gray-300 text-sm h-20 resize-none"
                                            />
                                        </div>

                                        <div>
                                            <label className="text-[10px] font-mono text-gray-500 block mb-1">LINK (HREF)</label>
                                            <input
                                                value={item.href}
                                                onChange={e => handleEditChange(i, 'href', e.target.value)}
                                                className="w-full bg-white/5 border border-white/10 p-2 text-neon-cyan font-mono text-xs"
                                            />
                                        </div>
                                    </div>
                                ) : (
                                    // Live Mode Card (Admin sees controls, user sees content)
                                    <div className="relative h-full">
                                        {/* Admin Inline Status Toggle */}
                                        {isAdmin && (
                                            <div className="absolute top-4 right-4 z-50">
                                                <button
                                                    onClick={(e) => {
                                                        e.preventDefault();
                                                        e.stopPropagation();
                                                        toggleItemStatus(i);
                                                    }}
                                                    className={`p-2 rounded-full backdrop-blur-md border shadow-lg transition-all ${isLive ? 'bg-neon-green/10 text-neon-green border-neon-green hover:bg-red-500 hover:border-red-500 hover:text-white' : 'bg-red-500 text-white border-red-500 hover:bg-neon-green hover:border-neon-green hover:text-black'}`}
                                                    title={isLive ? "Click to Disable" : "Click to Enable"}
                                                >
                                                    {isLive ? <Eye size={16} /> : <EyeOff size={16} />}
                                                </button>
                                            </div>
                                        )}

                                        <Link href={item.href} className={`block h-full ${!isLive ? 'pointer-events-none' : ''}`}>
                                            <motion.div
                                                whileHover={isLive ? { y: -5 } : {}}
                                                className={`p-8 bg-black/40 backdrop-blur-xl border border-white/10 ${isLive ? item.border : 'border-gray-800'} rounded-2xl transition-all duration-300 group hover:bg-black/60 flex flex-col h-full cursor-pointer relative overflow-hidden ${!isLive ? 'opacity-50 grayscale' : ''}`}
                                            >
                                                {!isLive && isAdmin && (
                                                    <div className="absolute top-0 left-0 bg-red-500 text-white text-[10px] font-mono px-3 py-1 z-50 rounded-br-lg">
                                                        DISABLED (USER VIEW: HIDDEN)
                                                    </div>
                                                )}

                                                <div className="mb-6 w-14 h-14 rounded-xl flex items-center justify-center bg-white/5 border border-white/10 relative z-10 transition-colors group-hover:border-white/20">
                                                    {ICON_MAP[item.iconType] || <Zap />}
                                                </div>
                                                <h3 className="text-xl md:text-2xl font-bold font-sans mb-3 text-white relative z-10">{item.title}</h3>
                                                <p className="font-sans text-sm text-gray-400 flex-grow relative z-10">{item.desc}</p>

                                                <div className="mt-8 flex justify-end relative z-10">
                                                    <span className="text-sm font-semibold text-gray-500 group-hover:text-white transition-colors flex items-center gap-2">
                                                        Access Vault <ArrowRight size={16} className="group-hover:translate-x-1 transition-transform" />
                                                    </span>
                                                </div>

                                                {/* Subtle hover gradient bloom */}
                                                {isLive && (
                                                    <div className={`absolute -inset-px opacity-0 group-hover:opacity-100 transition-opacity bg-gradient-to-br ${item.iconType === 'trophy' ? 'from-neon-cyan/10 to-transparent' :
                                                        item.iconType === 'award' ? 'from-purple-500/10 to-transparent' :
                                                            'from-neon-green/10 to-transparent'
                                                        } rounded-2xl pointer-events-none`}></div>
                                                )}
                                            </motion.div>
                                        </Link>
                                    </div>
                                )}
                            </div>
                        )
                    })}
                </div>
            </div>

            {/* Admin Save Bar */}
            <AnimatePresence>
                {isEditing && (
                    <motion.div
                        initial={{ y: 100 }}
                        animate={{ y: 0 }}
                        exit={{ y: 100 }}
                        className="fixed bottom-0 left-0 right-0 p-4 bg-black/90 backdrop-blur-md border-t border-neon-cyan z-50 flex items-center justify-between"
                    >
                        <div className="text-neon-cyan font-mono text-sm animate-pulse">
                            LOOTBOX_CONFIG // ADMIN_MODE
                        </div>
                        <div className="flex gap-4">
                            <button
                                onClick={() => {
                                    setIsEditing(false);
                                    setEditedItems(JSON.parse(JSON.stringify(items)));
                                }}
                                className="px-6 py-2 border border-red-500 text-red-500 font-mono text-sm hover:bg-red-500/10"
                            >
                                DISCARD
                            </button>
                            <button
                                onClick={saveChanges}
                                disabled={saving}
                                className="px-6 py-2 bg-neon-cyan text-black font-bold font-mono text-sm hover:opacity-80 disabled:opacity-50 flex items-center gap-2"
                            >
                                {saving ? <><StopCircle className="animate-spin" size={16} /> SAVING...</> : <><Save size={16} /> SAVE_CHANGES</>}
                            </button>
                        </div>
                    </motion.div>
                )}
            </AnimatePresence>
        </section>
    );
}

"use client";

import { motion, AnimatePresence } from "framer-motion";
import Link from "next/link";
import { ArrowRight, Play, Users, Crosshair, Rocket, Calendar, MapPin, Edit3, Save, Eye, EyeOff, StopCircle, X, Construction } from "lucide-react";
import { useEffect, useState } from "react";
import { collection, query, where, getDocs, limit, doc, getDoc, setDoc } from "firebase/firestore";
import { db } from "@/lib/firebase";

import { useAuth } from "@/context/AuthContext";

const DEFAULT_FEED_CONFIG = {
    featured: { enabled: true, title: "Featured Event" },
    active_ops: { enabled: true, title: "Prompt Engineering Lab" },
    incubator: { enabled: true, title: "Agent Builder Hub" },
    squadron: { enabled: true, title: "Agent Hackathon Sprints" },
    executor: { enabled: true, title: "Agent Showcase" },
};

export function MainFeed({ hasShownIntro }) {
    const { user, userData } = useAuth();
    const displayName = userData?.displayName || user?.email?.split('@')[0] || "OPERATIVE";
    const isAdmin = user?.email?.includes("admin");

    const [featuredHackathon, setFeaturedHackathon] = useState(null);
    const [loading, setLoading] = useState(true);

    // Admin Edit States
    const [config, setConfig] = useState(DEFAULT_FEED_CONFIG);
    const [isEditing, setIsEditing] = useState(false);
    const [saving, setSaving] = useState(false);

    useEffect(() => {
        const initData = async () => {
            try {
                // Fetch Featured Hackathon
                const q = query(
                    collection(db, "hackathons"),
                    where("isFeatured", "==", true),
                    limit(1)
                );
                const querySnapshot = await getDocs(q);
                if (!querySnapshot.empty) {
                    const docData = querySnapshot.docs[0].data();
                    setFeaturedHackathon({ id: querySnapshot.docs[0].id, ...docData });
                }

                // Fetch Config
                const configRef = doc(db, "system", "main_feed_config");
                const configSnap = await getDoc(configRef);
                if (configSnap.exists()) {
                    setConfig(configSnap.data());
                }
            } catch (error) {
                console.error("Error initializing MainFeed:", error);
            } finally {
                setLoading(false);
            }
        };

        initData();
    }, []);

    const toggleFeature = async (key) => {
        const newConfig = { ...config, [key]: { ...config[key], enabled: !config[key].enabled } };
        setConfig(newConfig);

        // Optimistic Save
        try {
            await setDoc(doc(db, "system", "main_feed_config"), newConfig);
        } catch (error) {
            console.error("Failed to toggle feature:", error);
            // Revert
            setConfig(config);
        }
    };

    const saveConfig = async () => {
        setSaving(true);
        try {
            await setDoc(doc(db, "system", "main_feed_config"), config);
            setIsEditing(false);
        } catch (error) {
            console.error("Failed to save config:", error);
        } finally {
            setSaving(false);
        }
    };

    const getLink = (hack) => {
        if (!hack) return "/hackathons";
        if (hack.registrationLink && hack.registrationLink.startsWith("/")) return hack.registrationLink;
        return `/hackathons/${hack.id}`;
    };

    // Helper Wrapper for Cards
    const FeatureWrapper = ({ featureKey, children, className = "" }) => {
        const isEnabled = config[featureKey]?.enabled ?? true;
        const showContent = isEnabled || isAdmin || isEditing;

        if (!showContent) return null; // Or return simplified placeholder if layout breaks? Prefer keeping grid intact.

        // If Disabled for User -> Show Under Construction
        if (!isEnabled && !isAdmin && !isEditing) {
            return (
                <div className={`bg-card-bg/50 border border-white/5 p-6 flex flex-col items-center justify-center text-center relative overflow-hidden grayscale opacity-75 min-h-[250px] ${className}`}>
                    <div className="absolute inset-0 stripes-bg opacity-10"></div>
                    <Construction className="text-yellow-500 mb-4 animate-pulse" size={32} />
                    <h3 className="text-lg font-bold font-sans text-gray-500 mb-2">UNDER CONSTRUCTION</h3>
                    <p className="font-mono text-xs text-gray-600">Module offline for upgrades.</p>
                    <div className="mt-4 px-2 py-1 bg-yellow-500/10 text-yellow-500 text-[9px] font-mono border border-yellow-500/20 rounded">
                        STATUS: 503
                    </div>
                </div>
            );
        }

        return (
            <div className={`relative ${className} ${!isEnabled ? 'opacity-60 grayscale' : ''}`}>
                {/* Admin Toggle Overlay */}
                {isAdmin && !isEditing && (
                    <div className="absolute top-2 right-2 z-50">
                        <button
                            onClick={(e) => {
                                e.preventDefault();
                                e.stopPropagation();
                                toggleFeature(featureKey);
                            }}
                            className={`p-2 rounded-full backdrop-blur-md border shadow-lg transition-all ${isEnabled ? 'bg-neon-green/10 text-neon-green border-neon-green hover:bg-black hover:text-white' : 'bg-red-500 text-white border-red-500 hover:bg-neon-green hover:border-neon-green hover:text-black'}`}
                            title={isEnabled ? "Click to Disable" : "Click to Enable"}
                        >
                            {isEnabled ? <Eye size={16} /> : <EyeOff size={16} />}
                        </button>
                    </div>
                )}

                {/* Admin Disabled Badge */}
                {!isEnabled && isAdmin && (
                    <div className="absolute top-0 left-0 bg-red-500 text-white text-[10px] font-mono px-2 py-1 z-40 pointer-events-none">
                        DISABLED (USER VIEW HIDDEN)
                    </div>
                )}

                {children}
            </div>
        );
    };

    return (
        <section className="pt-24 pb-12 px-4 min-h-[60vh] flex flex-col justify-center relative shadow-2xl z-10">
            <div className="absolute inset-0 grid-bg opacity-20 pointer-events-none"></div>

            <div className="max-w-6xl mx-auto w-full">
                <motion.div
                    initial={{ opacity: hasShownIntro ? 1 : 0, y: hasShownIntro ? 0 : 20 }}
                    animate={{ opacity: 1, y: 0 }}
                    transition={{ duration: hasShownIntro ? 0 : 0.5 }}
                    className="mb-8 border-b border-border pb-4 flex flex-col md:flex-row justify-between items-end"
                >
                    <div className="flex-1">
                        <div className="flex justify-between items-start">
                            <div>
                                <p className="font-mono text-neon-cyan text-xs mb-1 tracking-widest">// AGENT_GARAGE_ONLINE</p>
                                <h1 className="text-4xl md:text-6xl font-bold font-sans text-foreground">
                                    GARAGE OF <span className="text-neon-cyan">AI AGENTS</span>
                                </h1>
                            </div>
                            {isAdmin && (
                                <button
                                    onClick={() => {
                                        if (isEditing) saveConfig(); // Quick save
                                        else setIsEditing(true);
                                    }}
